import { useCallback, useMemo } from "react";
import { useDeckStore } from "../decks/useDeckStore";
import { DeckRecord } from "../decks/types";
import { ReviewMode, ReviewOrientation } from "./types";

type ReviewCard = {
  id: string;
  front: string;
  back: string;
};

type FlashOrderMode = "start" | "end" | "random";

type UseDeckReviewOptions = {
  orderMode?: FlashOrderMode;
  limit?: number;
};

export type ReviewSessionState = {
  currentIndex: number;
  round: number;
  cardOrder: string[];
  unknownCardIds: string[];
};

const shuffle = <T,>(arr: T[]): T[] => {
  const copy = [...arr];
  for (let i = copy.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = copy[i];
    copy[i] = copy[j] as T;
    copy[j] = tmp as T;
  }
  return copy;
};

const mapDeckToCards = (deck: DeckRecord, orientation: ReviewOrientation): ReviewCard[] =>
  deck.cards.map((card) =>
    orientation === "front-first"
      ? {
          id: card.id,
          front: card.front,
          back: card.back
        }
      : {
          id: card.id,
          front: card.back,
          back: card.front
        }
  );

export const useDeckReview = (
  deckId: string | undefined,
  mode: ReviewMode,
  orientation: ReviewOrientation,
  options: UseDeckReviewOptions = {}
) => {
  const deck = useDeckStore((state) => state.decks.find((item) => item.id === deckId));
  const rawState = useDeckStore((state) => (deckId ? state.reviewState[deckId] : undefined));
  const setDeckReviewState = useDeckStore((state) => state.setDeckReviewState);

  const reviewState = rawState && rawState.mode === mode ? rawState : undefined;
  const orderMode: FlashOrderMode = options.orderMode ?? "random";
  const sessionLimit = options.limit;

  const cards = useMemo(() => (deck ? mapDeckToCards(deck, orientation) : []), [deck, orientation]);
  const cardIndexMap = useMemo(
    () =>
      cards.reduce<Record<string, ReviewCard>>((acc, card) => {
        acc[card.id] = card;
        return acc;
      }, {}),
    [cards]
  );

  const buildOrder = useCallback(
    (source: string[]) => {
      const base = [...source];
      if (orderMode === "start") {
        return base;
      }
      if (orderMode === "end") {
        return base.reverse();
      }
      return shuffle(base);
    },
    [orderMode]
  );

  const startNewSession = useCallback(() => {
    if (!deckId || cards.length === 0) {
      return;
    }
    const ids = cards.map((card) => card.id);
    let cardOrder = buildOrder(ids);
    if (sessionLimit && sessionLimit > 0) {
      cardOrder = cardOrder.slice(0, Math.min(sessionLimit, cardOrder.length));
    }
    setDeckReviewState(
      deckId,
      {
        mode,
        cardOrder,
        currentIndex: 0,
        round: 1,
        unknownCardIds: [],
        lastUpdatedAt: new Date()
      } as any
    );
  }, [deckId, cards, mode, setDeckReviewState, buildOrder, sessionLimit]);

  const currentCard = useMemo(() => {
    if (!reviewState) {
      return undefined;
    }
    const id = reviewState.cardOrder[reviewState.currentIndex];
    if (!id) return undefined;
    return cardIndexMap[id];
  }, [cardIndexMap, reviewState]);

  const knownCardsCount = reviewState ? reviewState.cardOrder.length - reviewState.unknownCardIds.length : 0;
  const unknownCardsCount = reviewState ? reviewState.unknownCardIds.length : 0;
  const totalKnown =
    reviewState?.statusMap
      ? Object.values(reviewState.statusMap).filter((value) => value === "known").length
      : 0;
  const totalUnknown =
    reviewState?.statusMap
      ? Object.values(reviewState.statusMap).filter((value) => value === "unknown").length
      : 0;

  const markCard = useCallback(
    (known: boolean) => {
      if (!deckId || !reviewState) {
        return;
      }
      const currentCardId = reviewState.cardOrder[reviewState.currentIndex];
      if (!currentCardId) {
        return;
      }
      const nextUnknownSet = new Set(reviewState.unknownCardIds);
      if (known) {
        nextUnknownSet.delete(currentCardId);
      } else {
        nextUnknownSet.add(currentCardId);
      }
      const nextUnknownIds = Array.from(nextUnknownSet);
      const statusMap = {
        ...(reviewState.statusMap ?? {}),
        [currentCardId]: known ? "known" : "unknown"
      } as Record<string, "known" | "unknown">;
      const nextIndex = reviewState.currentIndex + 1;

      if (nextIndex >= reviewState.cardOrder.length) {
        setDeckReviewState(
          deckId,
          {
            mode,
            cardOrder: reviewState.cardOrder,
            currentIndex: reviewState.cardOrder.length,
            unknownCardIds: nextUnknownIds,
            round: reviewState.round,
            statusMap,
            lastUpdatedAt: new Date()
          } as any
        );
        return;
      }

      setDeckReviewState(
        deckId,
        {
          ...reviewState,
          currentIndex: nextIndex,
          unknownCardIds: nextUnknownIds,
          statusMap,
          lastUpdatedAt: new Date()
        } as any
      );
    },
    [deckId, reviewState, setDeckReviewState]
  );

  const startUnknownRound = useCallback(() => {
    if (!deckId || !reviewState || reviewState.unknownCardIds.length === 0) {
      return;
    }
    const nextOrder = buildOrder(reviewState.unknownCardIds);
    setDeckReviewState(
      deckId,
      {
        mode,
        cardOrder: nextOrder,
        currentIndex: 0,
        unknownCardIds: nextOrder,
        round: reviewState.round + 1,
        statusMap: reviewState.statusMap,
        lastUpdatedAt: new Date()
      } as any
    );
  }, [deckId, reviewState, mode, setDeckReviewState, buildOrder]);

  const resetProgress = useCallback(() => {
    if (!deckId) {
      return;
    }
    setDeckReviewState(deckId, undefined);
  }, [deckId, setDeckReviewState]);

  return {
    deck,
    cards,
    reviewState,
    currentCard,
    knownCardsCount,
    unknownCardsCount,
    totalKnown,
    totalUnknown,
    startNewSession,
    startUnknownRound,
    markCardAsKnown: useCallback(() => markCard(true), [markCard]),
    markCardAsUnknown: useCallback(() => markCard(false), [markCard]),
    resetProgress
  };
};
