import {
  listAppDataFiles,
  downloadAppDataFile,
  createAppDataJsonFile,
  updateAppDataJsonFile,
  deleteAppDataFile,
  DriveFileSummary
} from "@api-client/google-drive";
import { DeckRecord, deserializeDeck, serializeDeck, StoredDeckRecord } from "../types";
import {
  AppPreferences,
  DeckSyncConflict,
  DeckSyncMetadata,
  PendingDeckDeletion
} from "../useDeckStore";

const FILE_PREFIX = "deck";
const FILE_EXTENSION = ".json";
const PREFERENCES_FILE_NAME = "preferences.json";
const isDeckFileName = (name?: string | null) =>
  Boolean(name && name.startsWith(`${FILE_PREFIX}-`) && name.endsWith(FILE_EXTENSION));

const buildFileName = (deckId: string) => `${FILE_PREFIX}-${deckId}${FILE_EXTENSION}`;

const toUploadPayload = (deck: DeckRecord, syncTimestamp: Date): StoredDeckRecord => {
  const payloadDeck: DeckRecord = {
    ...deck,
    lastSyncedAt: syncTimestamp
  };
  return serializeDeck(payloadDeck);
};

const listDeckFiles = async (accessToken: string) => {
  const remoteFiles = await listAppDataFiles(accessToken, { pageSize: 1000 });
  return remoteFiles.filter((file) => isDeckFileName(file.name));
};

const downloadDeckDocument = async (accessToken: string, fileId: string): Promise<DeckRecord> => {
  const raw = (await downloadAppDataFile(accessToken, fileId)) as StoredDeckRecord;
  const parsed = deserializeDeck(raw);
  return {
    ...parsed,
    driveFileId: fileId,
    lastSyncedAt: parsed.lastSyncedAt ?? parsed.updatedAt
  };
};

const isPreferencesPayload = (data: unknown): data is AppPreferences => {
  if (!data || typeof data !== "object") {
    return false;
  }
  const { locale, theme } = data as Partial<AppPreferences>;
  return (
    typeof locale === "string" &&
    (locale === "en" || locale === "uk" || locale === "uk-les" || locale === "fr") &&
    typeof theme === "string" &&
    (theme === "light" || theme === "dark" || theme === "system")
  );
};

type PullResult = {
  updatedDecks: DeckRecord[];
  conflicts: DeckSyncConflict[];
};

export const pullDecksFromDrive = async (
  accessToken: string,
  decks: DeckRecord[],
  pendingDeletions: PendingDeckDeletion[] = []
): Promise<PullResult> => {
  const deckFiles = await listDeckFiles(accessToken);
  const deckMap = new Map(decks.map((deck) => [deck.id, deck]));
  const updatedDecks: DeckRecord[] = [];
  const conflicts: DeckSyncConflict[] = [];
  const pendingDeletionIds = new Set(pendingDeletions.map((item) => item.deckId));

  for (const file of deckFiles) {
    if (!file.id) {
      continue;
    }
    const remoteDeck = await downloadDeckDocument(accessToken, file.id);
    const localDeck = deckMap.get(remoteDeck.id);

    if (pendingDeletionIds.has(remoteDeck.id)) {
      continue;
    }

    if (!localDeck) {
      updatedDecks.push({
        ...remoteDeck,
        driveFileId: file.id,
        lastSyncedAt: new Date(remoteDeck.updatedAt)
      });
      continue;
    }

    const localUpdated = localDeck.updatedAt.getTime();
    const remoteUpdated = remoteDeck.updatedAt.getTime();
    const lastSynced = localDeck.lastSyncedAt?.getTime() ?? 0;

    const localChangedSinceSync = localUpdated > lastSynced;
    const remoteChangedSinceSync = remoteUpdated > lastSynced;

    if (!localChangedSinceSync && !remoteChangedSinceSync) {
      continue;
    }

    if (localChangedSinceSync && remoteChangedSinceSync) {
      conflicts.push({
        deckId: localDeck.id,
        driveFileId: file.id,
        local: {
          ...localDeck,
          driveFileId: file.id
        },
        remote: remoteDeck
      });
      continue;
    }

    if (remoteUpdated > localUpdated) {
      updatedDecks.push({
        ...remoteDeck,
        driveFileId: file.id,
        lastSyncedAt: new Date(remoteDeck.updatedAt)
      });
    }
  }

  return {
    updatedDecks,
    conflicts
  };
};

type PushResult = {
  deckId: string;
  metadata: DeckSyncMetadata;
}[];

export const pushDecksToDrive = async (
  accessToken: string,
  decks: DeckRecord[]
): Promise<PushResult> => {
  const pushed: PushResult = [];
  for (const deck of decks) {
    const lastSynced = deck.lastSyncedAt?.getTime() ?? 0;
    const needsPush = deck.updatedAt.getTime() > lastSynced || !deck.driveFileId;
    if (!needsPush) {
      continue;
    }
    const metadata = await uploadDeckToDrive({ accessToken, deck });
    pushed.push({
      deckId: deck.id,
      metadata
    });
  }
  return pushed;
};

export const pullPreferencesFromDrive = async (
  accessToken: string
): Promise<AppPreferences | undefined> => {
  const files = await listAppDataFiles(accessToken, {
    pageSize: 1,
    query: `name='${PREFERENCES_FILE_NAME}'`
  });
  const file = files[0];
  if (!file?.id) {
    return undefined;
  }
  try {
    const payload = await downloadAppDataFile(accessToken, file.id);
    if (isPreferencesPayload(payload)) {
      return payload;
    }
  } catch (error) {
    console.warn("Failed to read Drive preferences", error);
  }
  return undefined;
};

export const pushPreferencesToDrive = async (
  accessToken: string,
  preferences: AppPreferences
) => {
  const files = await listAppDataFiles(accessToken, {
    pageSize: 1,
    query: `name='${PREFERENCES_FILE_NAME}'`
  });
  const file = files[0];
  if (file?.id) {
    await updateAppDataJsonFile(accessToken, file.id, preferences);
  } else {
    await createAppDataJsonFile(accessToken, PREFERENCES_FILE_NAME, preferences);
  }
};

export const uploadDeckToDrive = async ({
  accessToken,
  deck
}: {
  accessToken: string;
  deck: DeckRecord;
}): Promise<DeckSyncMetadata> => {
  const syncTimestamp = new Date();
  if (deck.driveFileId) {
    await updateAppDataJsonFile(
      accessToken,
      deck.driveFileId,
      toUploadPayload(deck, syncTimestamp)
    );
    return {
      driveFileId: deck.driveFileId,
      lastSyncedAt: syncTimestamp
    };
  }

  const file = await createAppDataJsonFile(
    accessToken,
    buildFileName(deck.id),
    toUploadPayload(deck, syncTimestamp)
  );
  return {
    driveFileId: file.id,
    lastSyncedAt: syncTimestamp
  };
};

export const deleteDecksFromDrive = async (
  accessToken: string,
  pendingDeletions: PendingDeckDeletion[]
) => {
  const deleted: string[] = [];
  for (const entry of pendingDeletions) {
    if (!entry.driveFileId) {
      continue;
    }
    try {
      await deleteAppDataFile(accessToken, entry.driveFileId);
      deleted.push(entry.deckId);
    } catch (error) {
      const status =
        typeof error === "object" &&
        error !== null &&
        "response" in error &&
        (error as { response?: { status?: number } }).response?.status;
      if (status === 404) {
        deleted.push(entry.deckId);
      } else {
        console.warn("Failed to delete deck on Drive", entry.deckId, error);
      }
    }
  }
  return deleted;
};
