import { useMemo } from "react";
import { Button } from "@ui/components/Button";
import { useDeckStore } from "./useDeckStore";
import { useTranslation } from "../i18n/I18nProvider";
import { ReviewMode } from "../review/types";
import { FlashcardsIcon, LearnIcon, MatchIcon, TypeIcon } from "../components/icons";

type DeckManagerProps = {
  isAuthenticated: boolean;
  syncStatus: "idle" | "syncing" | "error" | "success";
  syncError?: string;
  lastSyncedLabel?: string;
  lockStatus?: "idle" | "acquiring" | "acquired" | "blocked" | "error";
  onEditDeck: (deckId: string) => void;
  onReviewDeck: (deckId: string, mode: ReviewMode) => void;
  onNewDeck?: () => void;
};

const formatDateTime = (date: Date | undefined) =>
  date
    ? new Intl.DateTimeFormat(undefined, {
        dateStyle: "medium",
        timeStyle: "short"
      }).format(date)
    : "—";

/** Readable label builder for Drive auto-sync status (replaces nested ternaries). */
type TFunc = (key: string, params?: Record<string, string | number>) => string;

type AutoSyncLockStatus = "idle" | "acquiring" | "acquired" | "blocked" | "error";
type AutoSyncSyncStatus = "idle" | "syncing" | "error" | "success";

type BuildAutoSyncParams = {
  isAuthenticated: boolean;
  lockStatus: AutoSyncLockStatus;
  syncStatus: AutoSyncSyncStatus;
  // exactOptionalPropertyTypes: when present, these may be undefined
  syncError?: string | undefined;
  lastSyncedLabel?: string | undefined;
};

