//   if (lockStatus === "blocked") return t("drive.autoSyncBlocked");
//   if (lockStatus === "error") return t("drive.autoSyncLockError");
//   if (lockStatus === "acquiring") return t("drive.autoSyncPreparing");
//   if (syncStatus === "error" && syncError) return t("drive.autoSyncError", { message: syncError });
//   if (syncStatus === "syncing") return t("drive.autoSyncActive");
//   if (lastSyncedLabel) return t("drive.autoSyncIdle", { timestamp: lastSyncedLabel });
//   return t("drive.autoSyncNever");
