export const DeckManager = ({
  isAuthenticated,
  syncStatus,
  syncError,
  lastSyncedLabel,
  lockStatus = "idle",
  onEditDeck,
  onReviewDeck,
  onNewDeck
}: DeckManagerProps) => {
  const { t } = useTranslation();
  const decks = useDeckStore((state) => state.decks);
  const deleteDeck = useDeckStore((state) => state.deleteDeck);

  const sortedDecks = useMemo(
    () => [...decks].sort((a, b) => b.updatedAt.getTime() - a.updatedAt.getTime()),
    [decks]
  );

  // const autoSyncLabel = useMemo(
  //   () =>
  //     buildAutoSyncLabel(t, {
  //       isAuthenticated,
  //       lockStatus,
  //       syncStatus,
  //       syncError,
  //       lastSyncedLabel
  //     }),
  //   [t, isAuthenticated, lockStatus, syncStatus, syncError, lastSyncedLabel]
  // );

  const lockOrErrorBanner = useMemo(() => {
    if (isAuthenticated && (lockStatus === "blocked" || lockStatus === "error")) {
      return {
        className:
          lockStatus === "blocked"
            ? "text-sm text-amber-500 dark:text-amber-400"
            : "text-sm text-red-500 dark:text-red-400",
        text:
          lockStatus === "blocked"
            ? t("drive.autoSyncBlocked")
            : t("drive.autoSyncLockError")
      };
    }
    if (syncStatus === "error" && syncError) {
      return {
        className: "text-sm text-red-500 dark:text-red-400",
        text: t("drive.autoSyncError", { message: syncError })
      };
    }
    return null;
  }, [isAuthenticated, lockStatus, syncStatus, syncError, t]);

  const handleDelete = (deckId: string) => {
    const deck = decks.find((item) => item.id === deckId);
    if (!deck) {
      return;
    }
    const confirmed = window.confirm(t("deck.confirmDelete", { title: deck.title }));
    if (confirmed) {
      deleteDeck(deckId);
    }
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h2 className="text-2xl font-semibold text-slate-900 dark:text-slate-100">
            {t("deck.workspaceTitle")}
          </h2>
          <p className="text-sm text-slate-600 dark:text-slate-400">
            {isAuthenticated ? t("deck.workspaceSubtitleAuthed") : t("deck.workspaceSubtitleGuest")}
          </p>
        </div>
      </header>

      {lockOrErrorBanner && (
        <p className={lockOrErrorBanner.className}>{lockOrErrorBanner.text}</p>
      )}

      {sortedDecks.length === 0 ? (
        <div className="ui-empty-panel">
          {t("deck.emptyState")}
        </div>
      ) : (
        <ul className="ui-vstack-4">
          {sortedDecks.map((deck) => (
            <li
              key={deck.id}
              className="ui-surface-panel"
            >
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div className="space-y-1">
                  <h3 className="text-lg font-semibold text-slate-900 dark:text-slate-100">
                    {deck.title}
                  </h3>
                  <p className="ui-text-xs-muted">
                    {t("deck.listSubtitle", {
                      count: deck.cards.length,
                      updated: formatDateTime(deck.updatedAt)
                    })}
                  </p>
                  {deck.description && (
                    <p className="text-sm text-slate-600 dark:text-slate-400">{deck.description}</p>
                  )}
                </div>
                <div className="flex flex-wrap items-center gap-2">
                  <Button size="sm" variant="outline" onClick={() => onEditDeck(deck.id)}>
                    {t("deck.editDeck")}
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    className="text-red-500 hover:text-red-400 dark:text-red-400 dark:hover:text-red-300"
                    onClick={() => handleDelete(deck.id)}
                  >
                    {t("deck.deleteDeck")}
                  </Button>
                </div>
              </div>
              <div className="mt-4 space-y-2">
                <div className="flex flex-wrap items-center gap-2">
                  <Button
                    size="sm"
                    variant="outline"
                    disabled={deck.cards.length === 0}
                    onClick={() => onReviewDeck(deck.id, "flashcards")}
                  >
                    <span className="flex items-center gap-2">
                      <FlashcardsIcon className="h-3.5 w-3.5" />
                      {t("review.mode.flashcardsLabel")}
                    </span>
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    disabled={deck.cards.length < 4}
                    title={deck.cards.length < 4 ? t("review.minCardsRequired", { count: 4 }) : undefined}
                    onClick={() => onReviewDeck(deck.id, "learn")}
                  >
                    <span className="flex items-center gap-2">
                      <LearnIcon className="h-3.5 w-3.5" />
                      {t("review.mode.learnLabel")}
                    </span>
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    disabled={deck.cards.length < 4}
                    title={deck.cards.length < 4 ? t("review.minCardsRequired", { count: 4 }) : undefined}
                    onClick={() => onReviewDeck(deck.id, "type")}
                  >
                    <span className="flex items-center gap-2">
                      <TypeIcon className="h-3.5 w-3.5" />
                      {t("review.mode.typeLabel")}
                    </span>
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    disabled={deck.cards.length < 4}
                    title={deck.cards.length < 4 ? t("review.minCardsRequired", { count: 4 }) : undefined}
                    onClick={() => onReviewDeck(deck.id, "match")}
                  >
                    <span className="flex items-center gap-2">
                      <MatchIcon className="h-3.5 w-3.5" />
                      {t("review.mode.matchLabel")}
                    </span>
                  </Button>
                </div>
              </div>
              <div className="mt-3 flex flex-wrap items-center gap-4 ui-text-xs-muted">
                <span>
                  {t("deck.lastSyncedLabel", { timestamp: formatDateTime(deck.lastSyncedAt) })}
                </span>
              </div>
            </li>
          ))}
        </ul>
      )}
      <div className="pt-2 flex justify-center md:justify-end">
        <Button
          size="sm"
          variant="primary"
          onClick={onNewDeck}
          disabled={!onNewDeck}
        >
          {t("deck.newDeck")}
        </Button>
      </div>
    </div>
  );
};
