import { useCallback, useMemo } from "react";
import { useDeckStore } from "../decks/useDeckStore";
import { DeckRecord } from "../decks/types";
import { ReviewOrientation } from "./types";

type LearnOption = { text: string; isCorrect: boolean };

type LearnQuestion = { prompt: string; answer: string; options: LearnOption[] };

export type LearnSessionOptions = {
  limit?: number;
  shuffle?: boolean;
};

const shuffle = <T,>(arr: T[]): T[] => {
  const copy = [...arr];
  for (let i = copy.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = copy[i];
    copy[i] = copy[j] as T;
    copy[j] = tmp as T;
  }
  return copy;
};

const mapTexts = (card: DeckRecord["cards"][number], orientation: ReviewOrientation) => {
  if (orientation === "front-first") {
    return { prompt: card.front, answer: card.back };
  }
  return { prompt: card.back, answer: card.front };
};

const clampLimit = (limit: number | undefined, max: number) => {
  if (!limit || limit <= 0) return undefined;
  return Math.min(Math.max(1, Math.floor(limit)), max);
};

export const useLearnReview = (
  deckId: string | undefined,
  orientation: ReviewOrientation,
  options: LearnSessionOptions = {}
) => {
  const deck = useDeckStore((state) => state.decks.find((d) => d.id === deckId));
  const rawState = useDeckStore((state) => (deckId ? state.reviewState[deckId] : undefined));
  const setDeckReviewState = useDeckStore((state) => state.setDeckReviewState);

  const reviewState = rawState && rawState.mode === "learn" ? rawState : undefined;

  const cards = useMemo(() => deck?.cards ?? [], [deck]);
  const normalizedOptions = useMemo(() => {
    const limit = clampLimit(options.limit, cards.length);
    return {
      limit,
      shuffle: options.shuffle !== false
    };
  }, [options.limit, options.shuffle, cards.length]);
  const cardIndexMap = useMemo(() => {
    const map: Record<string, DeckRecord["cards"][number]> = {};
    for (const c of cards) map[c.id] = c;
    return map;
  }, [cards]);

  const buildInitialOrder = useCallback(() => {
    let order = cards.map((c) => c.id);
    if (normalizedOptions.shuffle) {
      order = shuffle(order);
    }
    if (normalizedOptions.limit != null) {
      order = order.slice(0, normalizedOptions.limit);
    }
    return order;
  }, [cards, normalizedOptions]);

  const startNewSession = useCallback(() => {
    if (!deckId || cards.length === 0) return;
    const order = buildInitialOrder();
    if (order.length === 0) {
      return;
    }
    setDeckReviewState(deckId, {
      mode: "learn",
      cardOrder: order,
      currentIndex: 0,
      round: 1,
      unknownCardIds: [],
      lastUpdatedAt: new Date()
    } as any);
  }, [deckId, cards, buildInitialOrder, setDeckReviewState]);

  const currentCard = useMemo(() => {
    if (!reviewState) return undefined;
    const id = reviewState.cardOrder[reviewState.currentIndex];
    if (!id) return undefined;
    return cardIndexMap[id];
  }, [cardIndexMap, reviewState]);

  const question: LearnQuestion | undefined = useMemo(() => {
    if (!currentCard) return undefined;
    const { prompt, answer } = mapTexts(currentCard, orientation);
    const pool = cards
      .filter((c) => c.id !== currentCard.id)
      .map((c) => mapTexts(c, orientation).answer);
    let distractors = shuffle(pool).slice(0, 3);
    if (distractors.length < 3) {
      const filler: string[] = pool.length > 0 ? pool : [answer];
      while (distractors.length < 3) {
        const idx = Math.floor(Math.random() * filler.length);
        const candidate = filler[idx] ?? answer;
        distractors.push(candidate);
      }
    }
    const options = shuffle<LearnOption>([
      { text: answer, isCorrect: true },
      ...distractors.map((text) => ({ text, isCorrect: false }))
    ]);
    return { prompt, answer, options };
  }, [currentCard, cards, orientation]);

  const knownCardsCount =
    reviewState ? reviewState.cardOrder.length - reviewState.unknownCardIds.length : 0;
  const unknownCardsCount = reviewState ? reviewState.unknownCardIds.length : 0;
  const totalKnown =
    reviewState?.statusMap
      ? Object.values(reviewState.statusMap).filter((v) => v === "known").length
      : 0;
  const totalUnknown =
    reviewState?.statusMap
      ? Object.values(reviewState.statusMap).filter((v) => v === "unknown").length
      : 0;

  const handleSelect = useCallback(
    (selectedIndex: number) => {
      if (!deckId || !reviewState || !question) return false;
      const isCorrect = question.options[selectedIndex]?.isCorrect === true;
      const currentCardId = reviewState.cardOrder[reviewState.currentIndex];
      if (!currentCardId) return isCorrect;

      // Compute next state now, but delay applying it so UI feedback remains visible
      const nextUnknownSet = new Set(reviewState.unknownCardIds);
      if (isCorrect) nextUnknownSet.delete(currentCardId);
      else nextUnknownSet.add(currentCardId);
      const nextUnknownIds = Array.from(nextUnknownSet);
      const statusMap = {
        ...(reviewState.statusMap ?? {}),
        [currentCardId]: isCorrect ? "known" : "unknown"
      } as Record<string, "known" | "unknown">;
      const nextIndex = reviewState.currentIndex + 1;

      if (nextIndex >= reviewState.cardOrder.length) {
        setDeckReviewState(deckId, {
          mode: "learn",
          cardOrder: reviewState.cardOrder,
          currentIndex: reviewState.cardOrder.length,
          unknownCardIds: nextUnknownIds,
          round: reviewState.round,
          statusMap,
          lastUpdatedAt: new Date()
        } as any);
      } else {
        setDeckReviewState(deckId, {
          ...reviewState,
          currentIndex: nextIndex,
          unknownCardIds: nextUnknownIds,
          statusMap,
          lastUpdatedAt: new Date()
        } as any);
      }

      return isCorrect;
    },
    [deckId, reviewState, question, setDeckReviewState]
  );

  const startUnknownRound = useCallback(() => {
    if (!deckId || !reviewState || reviewState.unknownCardIds.length === 0) return;
    const nextOrder = normalizedOptions.shuffle
      ? shuffle(reviewState.unknownCardIds)
      : reviewState.unknownCardIds;
    setDeckReviewState(deckId, {
      mode: "learn",
      cardOrder: nextOrder,
      currentIndex: 0,
      unknownCardIds: nextOrder,
      round: reviewState.round + 1,
      statusMap: reviewState.statusMap,
      lastUpdatedAt: new Date()
    } as any);
  }, [deckId, reviewState, setDeckReviewState, normalizedOptions.shuffle]);

  const resetProgress = useCallback(() => {
    if (!deckId) return;
    setDeckReviewState(deckId, undefined);
  }, [deckId, setDeckReviewState]);

  const isSummary =
    reviewState != null &&
    reviewState.currentIndex >= reviewState.cardOrder.length &&
    (deck?.cards?.length ?? 0) > 0;
  const inProgress =
    reviewState != null &&
    reviewState.currentIndex < reviewState.cardOrder.length &&
    !!currentCard;

  return {
    deck,
    reviewState,
    currentCard,
    question,
    knownCardsCount,
    unknownCardsCount,
    totalKnown,
    totalUnknown,
    startNewSession,
    startUnknownRound,
    handleSelect,
    resetProgress,
    isSummary,
    inProgress,
    nextRoundUnknownCount: reviewState?.unknownCardIds.length ?? 0
  };
};
