import {
  createAppDataJsonFile,
  deleteAppDataFile,
  downloadAppDataFile,
  listAppDataFiles,
  updateAppDataJsonFile
} from "@api-client/google-drive";

const LOCK_FILE_NAME = "nova-lock.json";
export const LOCK_DURATION_MS = 150_000;
export const LOCK_REFRESH_INTERVAL_MS = 120_000;

type DriveLockPayload = {
  ownerId: string;
  expiresAt: string;
  updatedAt: string;
};

const nowIso = () => new Date().toISOString();

const parsePayload = (data: unknown): DriveLockPayload | undefined => {
  if (!data || typeof data !== "object") {
    return undefined;
  }
  const { ownerId, expiresAt, updatedAt } = data as Record<string, unknown>;
  if (typeof ownerId !== "string" || typeof expiresAt !== "string") {
    return undefined;
  }
  return {
    ownerId,
    expiresAt,
    updatedAt: typeof updatedAt === "string" ? updatedAt : nowIso()
  };
};

const getLockFile = async (accessToken: string) => {
  const files = await listAppDataFiles(accessToken, {
    pageSize: 1,
    query: `name='${LOCK_FILE_NAME}'`
  });
  const file = files[0];
  if (!file?.id) {
    return undefined;
  }
  try {
    const payload = parsePayload(await downloadAppDataFile(accessToken, file.id));
    return {
      file,
      payload
    };
  } catch (error) {
    console.warn("Failed to download Drive lock payload", error);
    return {
      file,
      payload: undefined
    };
  }
};

const toPayload = (ownerId: string, durationMs: number): DriveLockPayload => {
  const expiresAt = new Date(Date.now() + durationMs).toISOString();
  return {
    ownerId,
    expiresAt,
    updatedAt: nowIso()
  };
};

type AcquireResult =
  | {
      status: "acquired";
      fileId: string;
      expiresAt: Date;
    }
  | {
      status: "blocked";
      fileId: string;
      expiresAt?: Date;
      ownerId?: string;
    };

export const acquireDriveLock = async ({
  accessToken,
  ownerId,
  durationMs = LOCK_DURATION_MS
}: {
  accessToken: string;
  ownerId: string;
  durationMs?: number;
}): Promise<AcquireResult> => {
  const existing = await getLockFile(accessToken);
  const payload = toPayload(ownerId, durationMs);

  if (!existing) {
    const created = await createAppDataJsonFile(accessToken, LOCK_FILE_NAME, payload);
    return {
      status: "acquired",
      fileId: created.id,
      expiresAt: new Date(payload.expiresAt)
    };
  }

  const fileId = existing.file.id;
  const remotePayload = existing.payload;
  const now = Date.now();

  if (!remotePayload || remotePayload.ownerId === ownerId) {
    await updateAppDataJsonFile(accessToken, fileId, payload);
    return {
      status: "acquired",
      fileId,
      expiresAt: new Date(payload.expiresAt)
    };
  }

  const remoteExpires = Date.parse(remotePayload.expiresAt);
  if (Number.isNaN(remoteExpires) || remoteExpires <= now) {
    await updateAppDataJsonFile(accessToken, fileId, payload);
    return {
      status: "acquired",
      fileId,
      expiresAt: new Date(payload.expiresAt)
    };
  }

  return {
    status: "blocked",
    fileId,
    ownerId: remotePayload.ownerId,
    expiresAt: new Date(remoteExpires)
  };
};

type RefreshResult =
  | {
      status: "ok";
      expiresAt: Date;
    }
  | {
      status: "lost";
      expiresAt?: Date;
      ownerId?: string;
    };

export const refreshDriveLock = async ({
  accessToken,
  ownerId,
  fileId,
  durationMs = LOCK_DURATION_MS
}: {
  accessToken: string;
  ownerId: string;
  fileId: string;
  durationMs?: number;
}): Promise<RefreshResult> => {
  if (!fileId) {
    return { status: "lost" };
  }
  const data = parsePayload(await downloadAppDataFile(accessToken, fileId));
  if (data && data.ownerId !== ownerId) {
    const expiresAt = Date.parse(data.expiresAt);
    return {
      status: "lost",
      expiresAt: Number.isNaN(expiresAt) ? undefined : new Date(expiresAt),
      ownerId: data.ownerId
    };
  }

  const payload = toPayload(ownerId, durationMs);
  await updateAppDataJsonFile(accessToken, fileId, payload);
  return {
    status: "ok",
    expiresAt: new Date(payload.expiresAt)
  };
};

export const releaseDriveLock = async ({
  accessToken,
  ownerId,
  fileId
}: {
  accessToken: string;
  ownerId: string;
  fileId: string | null;
}) => {
  if (!fileId) {
    return;
  }
  try {
    const data = parsePayload(await downloadAppDataFile(accessToken, fileId));
    if (data && data.ownerId !== ownerId) {
      return;
    }
    await deleteAppDataFile(accessToken, fileId);
  } catch (error) {
    console.warn("Failed to release Drive lock", error);
  }
};

export const getDriveLockSnapshot = async (accessToken: string) => {
  const entry = await getLockFile(accessToken);
  if (!entry) {
    return undefined;
  }
  const fileId = entry.file.id;
  const payload = entry.payload;
  if (!payload) {
    return {
      fileId,
      payload: undefined
    };
  }
  const expiresAt = Date.parse(payload.expiresAt);
  return {
    fileId,
    payload: {
      ownerId: payload.ownerId,
      expiresAt: Number.isNaN(expiresAt) ? undefined : new Date(expiresAt)
    }
  };
};
