import { forwardRef } from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, VariantProps } from "class-variance-authority";
import clsx from "clsx";

const buttonStyles = cva(
  "inline-flex items-center justify-center gap-2 rounded-2xl px-4 py-2 text-sm font-semibold transition focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 disabled:cursor-not-allowed",
  {
    variants: {
      variant: {
        primary:
          "border border-transparent bg-emerald-600 text-white shadow-[0_18px_40px_-18px_rgba(16,185,129,0.7)] hover:bg-emerald-500 focus-visible:outline-emerald-300 disabled:bg-emerald-300 disabled:text-white/80 disabled:border-transparent",
        secondary:
          "border border-slate-400 bg-white text-slate-900 shadow-sm hover:border-slate-500 hover:bg-slate-50 focus-visible:outline-slate-500 disabled:bg-slate-100 disabled:text-slate-400 disabled:border-slate-200 dark:border-white/15 dark:bg-white/10 dark:text-white dark:hover:bg-white/15",
        ghost:
          "border border-transparent bg-transparent text-slate-700 hover:bg-slate-100 focus-visible:outline-slate-400 disabled:text-slate-400 disabled:bg-transparent dark:text-slate-200 dark:hover:bg-white/10",
        outline:
          "border border-slate-400 bg-transparent text-slate-800 hover:bg-slate-50 focus-visible:outline-slate-500 disabled:border-slate-200 disabled:text-slate-400 disabled:bg-transparent dark:border-white/20 dark:text-white dark:hover:bg-white/10",
        glass:
          "border border-slate-300 bg-white/90 text-slate-800 shadow-sm backdrop-blur hover:bg-white focus-visible:outline-slate-400 disabled:border-slate-200 disabled:text-slate-400 dark:border-white/50 dark:bg-white/10 dark:text-white dark:hover:bg-white/15",
        warning:
          "border border-amber-300 bg-amber-50 text-slate-900 shadow-sm hover:bg-amber-100 focus-visible:outline-amber-300 disabled:border-amber-200 disabled:text-slate-400 disabled:bg-amber-100 dark:border-amber-300/60 dark:bg-amber-400/20 dark:text-white dark:hover:bg-amber-300/25"
      },
      size: {
        sm: "h-9 px-3 text-xs",
        md: "h-10 px-4 text-sm",
        lg: "h-12 px-5 text-base"
      }
    },
    defaultVariants: {
      variant: "secondary",
      size: "md"
    }
  }
);

type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> &
  VariantProps<typeof buttonStyles> & {
    asChild?: boolean;
  };

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Component = asChild ? Slot : "button";
    return (
      <Component ref={ref} className={clsx(buttonStyles({ variant, size }), className)} {...props} />
    );
  }
);

Button.displayName = "Button";
