import { useMemo } from "react";
import { GlassModal } from "@ui/components/GlassModal";
import { MatchIcon } from "../components/icons";
import { useTranslation } from "../i18n/I18nProvider";
import { useMatchReview } from "./useMatchReview";
import { MatchBoard } from "./MatchBoard";
import { MatchHistory } from "./MatchHistory";

type MatchReviewModalProps = {
  deckId?: string;
  isOpen: boolean;
  onClose: () => void;
  minCardsRequired: number;
};

export const MatchReviewModal = ({
  deckId,
  isOpen,
  onClose,
  minCardsRequired
}: MatchReviewModalProps) => {
  const { t } = useTranslation();
  const match = useMatchReview(deckId, "front-first");
  const deck = match.deck;
  const hasCards = Boolean(deck && deck.cards.length > 0);
  const hasEnough = Boolean(deck && deck.cards.length >= minCardsRequired);

  const statusText = useMemo(() => {
    if (!hasCards) return t("review.emptyDeck");
    if (!hasEnough) return t("review.minCardsRequired", { count: minCardsRequired });
    return null;
  }, [hasCards, hasEnough, minCardsRequired, t]);

  return (
    <GlassModal open={isOpen} onClose={onClose} panelClassName="max-w-4xl" contentClassName="text-slate-900 dark:text-slate-50">
      <header className="flex flex-wrap items-start justify-between gap-3 md:gap-4">
        <div className="space-y-2">
          <p className="flex items-center gap-2 text-xs uppercase tracking-wide text-brand-400">
            <span className="text-brand-500">
              <MatchIcon className="h-4 w-4" />
            </span>
            {t("review.mode.matchLabel")}
          </p>
          <h2 className="text-xl md:text-2xl font-semibold text-slate-900 dark:text-slate-50">
            {deck ? deck.title : t("review.selectDeck")}
          </h2>
          {deck?.description && (
            <p className="hidden md:block text-sm text-slate-700 dark:text-slate-400">{deck.description}</p>
          )}
          <p className="hidden md:block text-sm text-slate-700 dark:text-slate-500">{t("review.startDescription")}</p>
        </div>
      </header>

      {statusText && <div className="ui-empty-panel">{statusText}</div>}

      {hasEnough && deck && (
        <div className="ui-vstack-4">
          <MatchBoard
            deckTitle={deck?.title}
            grid={match.grid}
            setGrid={match.setGrid}
            tiles={match.tiles.map((t) => ({
              key: t.key,
              text: t.text,
              matched: t.matched,
              side: t.side
            }))}
            selected={match.selected}
            selectTile={match.selectTile}
            mistakes={match.mistakes}
            elapsedMs={match.elapsedMs}
            completed={match.completed}
            score={match.score}
            pairs={match.pairs}
            started={match.started}
            canStart={match.canStart}
            startGame={match.startGame}
            stopGame={match.stopGame}
          />
          {(!match.started || match.completed) && (
            <MatchHistory
              results={deck.matchResults}
              grid={match.grid}
              highlightTimestamp={match.latestResultTimestamp}
            />
          )}
        </div>
      )}
    </GlassModal>
  );
};
