import { GOOGLE_DRIVE_SCOPES, GOOGLE_SCRIPT_URL } from "./constants";

declare global {
  interface Window {
    google?: typeof google;
    __movaGoogleScriptPromise__?: Promise<typeof google>;
  }

  const google: {
    accounts: {
      oauth2: {
        initTokenClient(config: TokenClientConfig): GoogleOAuth2TokenClient;
      };
    };
  };
}

type TokenClientConfig = {
  client_id: string;
  scope: string;
  prompt?: "" | "consent" | "select_account";
  callback: (tokenResponse: TokenResponse) => void;
  error_callback?: (error: GoogleOAuthError) => void;
};

export type GoogleOAuth2TokenClient = {
  requestAccessToken(options?: { prompt?: "" | "consent" | "select_account" }): void;
};

export type TokenResponse = {
  access_token: string;
  expires_in: number;
  scope: string;
  token_type: "Bearer";
};

export type GoogleOAuthError = {
  type: string;
  message: string;
};

export type GoogleAuthConfig = {
  clientId: string;
  scopes?: string;
};

const loadGoogleScript = (): Promise<typeof google> => {
  if (window.google) {
    return Promise.resolve(window.google);
  }

  if (window.__movaGoogleScriptPromise__) {
    return window.__movaGoogleScriptPromise__;
  }

  window.__movaGoogleScriptPromise__ = new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = GOOGLE_SCRIPT_URL;
    script.async = true;
    script.onload = () => {
      if (window.google) {
        resolve(window.google);
      } else {
        reject(new Error("Google script loaded but google object not available."));
      }
    };
    script.onerror = () => reject(new Error("Failed to load Google Identity Services script."));
    document.head.appendChild(script);
  });

  return window.__movaGoogleScriptPromise__;
};

export const initGoogleDriveTokenClient = async (
  config: GoogleAuthConfig,
  opts?: {
    prompt?: "" | "consent" | "select_account";
  }
) => {
  if (!config.clientId) {
    throw new Error("Google client id is required");
  }

  const google = await loadGoogleScript();
  let tokenResolver: (value: TokenResponse) => void;
  let tokenRejecter: (reason?: unknown) => void;

  const tokenPromise = new Promise<TokenResponse>((resolve, reject) => {
    tokenResolver = resolve;
    tokenRejecter = reject;
  });

  const client = google.accounts.oauth2.initTokenClient({
    client_id: config.clientId,
    scope: config.scopes ?? GOOGLE_DRIVE_SCOPES,
    prompt: opts?.prompt ?? "",
    callback: (tokenResponse) => {
      tokenResolver(tokenResponse);
    },
    error_callback: (error) => {
      tokenRejecter(error);
    }
  });

  return {
    client,
    requestAccessToken: (requestOptions?: { prompt?: "" | "consent" | "select_account" }) => {
      client.requestAccessToken(requestOptions);
      return tokenPromise;
    }
  };
};
