import clsx from "clsx";
import { useCallback, useEffect, useRef, useState } from "react";
import { Button } from "@ui/components/Button";
import { useTranslation } from "../i18n/I18nProvider";

type ReviewCardProps = {
  front: string;
  back: string;
  onKnow: () => void;
  onDontKnow: () => void;
  onReverseOrientation: () => void;
};

const SWIPE_THRESHOLD = 200;

export const ReviewCard = ({
  front,
  back,
  onKnow,
  onDontKnow,
  onReverseOrientation
}: ReviewCardProps) => {
  const { t } = useTranslation();
  const [showBack, setShowBack] = useState(false);
  const [dragOffset, setDragOffset] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const [highlight, setHighlight] = useState<"known" | "unknown" | null>(null);

  const pointerStartRef = useRef<number | null>(null);
  const triggeredRef = useRef(false);
  const resetTimeoutRef = useRef<number | null>(null);
  const highlightTimeoutRef = useRef<number | null>(null);

  const resetOffset = useCallback(
    (delay = 350) => {
      if (resetTimeoutRef.current) {
        window.clearTimeout(resetTimeoutRef.current);
      }
      resetTimeoutRef.current = window.setTimeout(() => {
        setDragOffset(0);
        resetTimeoutRef.current = null;
      }, delay);
    },
    []
  );

  const setHighlightFor = useCallback((value: "known" | "unknown") => {
    if (highlightTimeoutRef.current) {
      window.clearTimeout(highlightTimeoutRef.current);
    }
    setHighlight(value);
    highlightTimeoutRef.current = window.setTimeout(() => {
      setHighlight(null);
      highlightTimeoutRef.current = null;
    }, 320);
  }, []);

  const commit = useCallback(
    (known: boolean) => {
      if (triggeredRef.current) return;
      triggeredRef.current = true;
      pointerStartRef.current = null;
      setIsDragging(false);
      setDragOffset(known ? 240 : -240);
      resetOffset();
      setHighlightFor(known ? "known" : "unknown");
      setShowBack(false);
      if (known) {
        onKnow();
      } else {
        onDontKnow();
      }
    },
    [onDontKnow, onKnow, resetOffset, setHighlightFor]
  );

  const handleSwipe = useCallback(
    (deltaX: number) => {
      if (Math.abs(deltaX) < SWIPE_THRESHOLD) {
        return;
      }
      commit(deltaX > 0);
    },
    [commit]
  );

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === " ") {
        event.preventDefault();
        setShowBack((prev) => !prev);
        return;
      }
      if (event.key === "ArrowRight") {
        event.preventDefault();
        commit(true);
        return;
      }
      if (event.key === "ArrowLeft") {
        event.preventDefault();
        commit(false);
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [commit]);

  useEffect(
    () => () => {
      if (resetTimeoutRef.current) {
        window.clearTimeout(resetTimeoutRef.current);
      }
    },
    []
  );

  useEffect(() => {
    triggeredRef.current = false;
    setShowBack(false);
    setDragOffset(0);
  }, [front, back]);

  useEffect(
    () => () => {
      if (resetTimeoutRef.current) {
        window.clearTimeout(resetTimeoutRef.current);
      }
      if (highlightTimeoutRef.current) {
        window.clearTimeout(highlightTimeoutRef.current);
      }
    },
    []
  );

  useEffect(() => {
    triggeredRef.current = false;
    setShowBack(false);
    setDragOffset(0);
    setHighlight(null);
  }, [front, back]);

  const intensity = Math.min(Math.abs(dragOffset) / SWIPE_THRESHOLD, 1);
  const swipeShadow =
    dragOffset > 0
      ? `0 28px 48px -20px rgba(16, 185, 129, ${0.55 * intensity})`
      : dragOffset < 0
      ? `0 28px 48px -20px rgba(249, 115, 22, ${0.55 * intensity})`
      : undefined;
  const highlightClass = clsx(
    highlight === "known" && "ui-swipe-known",
    highlight === "unknown" && "ui-swipe-unknown",
    !highlight && "ui-swipe-neutral"
  );

  return (
    <div
      className={clsx("ui-quiz-card transition", highlightClass)}
      style={{
        transform: `translateX(${dragOffset}px) rotate(${(dragOffset / 12).toFixed(2)}deg)`,
        transition: isDragging ? "none" : "transform 0.2s ease-out",
        boxShadow: swipeShadow
      }}
      onPointerDown={(event) => {
        pointerStartRef.current = event.clientX;
        triggeredRef.current = false;
        setIsDragging(true);
        setDragOffset(0);
      }}
      onPointerMove={(event) => {
        if (pointerStartRef.current == null || triggeredRef.current) {
          return;
        }
        const offset = event.clientX - pointerStartRef.current;
        setDragOffset(offset);
        if (Math.abs(offset) >= SWIPE_THRESHOLD) {
          handleSwipe(offset);
        }
      }}
      onPointerUp={() => {
        pointerStartRef.current = null;
        setIsDragging(false);
        setDragOffset(0);
      }}
      onPointerCancel={() => {
        pointerStartRef.current = null;
        setIsDragging(false);
        setDragOffset(0);
      }}
      onPointerLeave={() => {
        pointerStartRef.current = null;
        setIsDragging(false);
        setDragOffset(0);
      }}
    >
      <div className="space-y-4 text-left">
        <p className="ui-kicker">
          {showBack ? t("review.cardBack") : t("review.cardFront")}
        </p>
        <p className="whitespace-pre-wrap break-words ui-title-xl">
          {showBack ? back : front}
        </p>
      </div>
      <ButtonRow
        onFlip={() => setShowBack((prev) => !prev)}
      />
    </div>
  );
};

const ButtonRow = ({
  onFlip
}: {
  onFlip: () => void;
}) => {
  const { t } = useTranslation();
  return (
    <div className="flex">
      <Button
        variant="secondary"
        onClick={onFlip}
        className="flex-1"
      >
        {t("review.flipCard")}
      </Button>
    </div>
  );
};
