import { createContext, useContext, useEffect, useMemo, useState } from "react";
import { useDeckStore } from "../decks/useDeckStore";
import { ThemePreference } from "./types";
type ResolvedTheme = "light" | "dark";

type ThemeContextValue = {
  theme: ThemePreference;
  resolvedTheme: ResolvedTheme;
  setTheme: (theme: ThemePreference) => void;
};

const ThemeContext = createContext<ThemeContextValue | undefined>(undefined);

const getSystemTheme = (): ResolvedTheme => {
  if (typeof window === "undefined") {
    return "dark";
  }
  return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
};

const applyDocumentTheme = (mode: ResolvedTheme) => {
  if (typeof document === "undefined") {
    return;
  }
  document.documentElement.classList.toggle("dark", mode === "dark");
};

type ThemeProviderProps = {
  children: React.ReactNode;
};

export const ThemeProvider = ({ children }: ThemeProviderProps) => {
  const theme = useDeckStore((state) => state.preferences.theme);
  const setThemePreference = useDeckStore((state) => state.setThemePreference);
  const [resolvedTheme, setResolvedTheme] = useState<ResolvedTheme>(() => getSystemTheme());

  useEffect(() => {
    const targetTheme = theme === "system" ? getSystemTheme() : theme;
    applyDocumentTheme(targetTheme);
    setResolvedTheme(targetTheme);
  }, [theme]);

  useEffect(() => {
    if (typeof window === "undefined" || theme !== "system") {
      return;
    }
    const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");
    const handleChange = (event: MediaQueryListEvent) => {
      const mode: ResolvedTheme = event.matches ? "dark" : "light";
      applyDocumentTheme(mode);
      setResolvedTheme(mode);
    };
    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, [theme]);

  const value = useMemo<ThemeContextValue>(
    () => ({
      theme,
      resolvedTheme,
      setTheme: setThemePreference
    }),
    [theme, resolvedTheme, setThemePreference]
  );

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
};

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error("useTheme must be used within a ThemeProvider");
  }
  return context;
};
