import { useCallback, useEffect, useState } from "react";
import { useTranslation } from "../i18n/I18nProvider";
import { useGrowl } from "@ui/components/Growl";

type LearnCardProps = {
  prompt: string;
  answer: string;
  options: { text: string }[]; // UI doesn't need to know which is correct
  onSelect: (index: number) => boolean; // returns true if correct; also advances session
};

export const LearnCard = ({ prompt, answer, options, onSelect }: LearnCardProps) => {
  const { t } = useTranslation();
  const { showGrowl } = useGrowl();
  const [locked, setLocked] = useState(false);

  useEffect(() => {
    setLocked(false);
  }, [prompt, options]);

  const handleSelect = useCallback(
    (index: number) => {
      if (locked) return;
      setLocked(true);
      const correct = onSelect(index);
      showGrowl(
        correct
          ? {
              tone: "success",
              message: t("review.learn.correct")
            }
          : {
              tone: "warning",
              message: t("review.learn.incorrect", { answer })
            }
      );
    },
    [locked, onSelect, showGrowl, t, answer]
  );

  return (
    <div className="ui-quiz-card">
      <div className="space-y-4 text-left">
        <p className="ui-kicker">
          {t("review.learn.prompt")}
        </p>
        <p className="ui-prewrap ui-title-2xl">
          {prompt}
        </p>
      </div>

      <div className="mt-4 grid gap-3 md:mt-5 md:grid-cols-2">
        {options.map((opt, idx) => {
          return (
            <button
              key={`${opt.text}-${idx}`}
              type="button"
              onClick={() => handleSelect(idx)}
              className="ui-option"
              disabled={locked}
            >
              {opt.text}
            </button>
          );
        })}
      </div>
    </div>
  );
};
