import { useCallback } from "react";
import { useDeckStore } from "./useDeckStore";
import {
  pullDecksFromDrive,
  pushDecksToDrive,
  uploadDeckToDrive,
  pullPreferencesFromDrive,
  pushPreferencesToDrive,
  deleteDecksFromDrive
} from "./sync/googleDriveSync";

export const useDeckSync = () => {
  const markSyncStatus = useDeckStore((state) => state.markSyncStatus);
  const replaceDeck = useDeckStore((state) => state.replaceDeck);
  const setDeckSyncMetadata = useDeckStore((state) => state.setDeckSyncMetadata);
  const setLocalChanges = useDeckStore((state) => state.setLocalChanges);
  const setPreferences = useDeckStore((state) => state.setPreferences);
  const conflicts = useDeckStore((state) => state.conflicts);
  const setConflicts = useDeckStore((state) => state.setConflicts);
  const clearConflicts = useDeckStore((state) => state.clearConflicts);
  const syncStatus = useDeckStore((state) => state.syncStatus);
  const syncError = useDeckStore((state) => state.syncError);
  const removePendingDeletions = useDeckStore((state) => state.removePendingDeletions);

  const pullFromDrive = useCallback(
    async (accessToken: string) => {
      markSyncStatus("syncing");
      try {
        const decks = useDeckStore.getState().decks;
        const pendingDeletions = useDeckStore.getState().pendingDeletions;
        const { updatedDecks, conflicts: pendingConflicts } = await pullDecksFromDrive(
          accessToken,
          decks,
          pendingDeletions
        );

        const now = new Date();
        updatedDecks.forEach((deck) => {
          replaceDeck(deck);
          setDeckSyncMetadata(deck.id, {
            driveFileId: deck.driveFileId,
            lastSyncedAt: deck.lastSyncedAt ?? now
          });
        });

        const remotePreferences = await pullPreferencesFromDrive(accessToken);
        if (remotePreferences) {
          setPreferences(remotePreferences);
        }

        setConflicts(pendingConflicts);
        setLocalChanges(false);
        markSyncStatus("success");
      } catch (error) {
        const message =
          error instanceof Error ? error.message : "Failed to pull decks from Google Drive.";
        markSyncStatus("error", message);
        console.error(error);
      }
    },
    [markSyncStatus, replaceDeck, setDeckSyncMetadata, setConflicts, setPreferences, setLocalChanges]
  );

  const pushLocalChanges = useCallback(
    async (accessToken: string) => {
      markSyncStatus("syncing");
      try {
        const decks = useDeckStore.getState().decks;
        const pushed = await pushDecksToDrive(accessToken, decks);
        pushed.forEach(({ deckId, metadata }) => {
          setDeckSyncMetadata(deckId, metadata);
        });
        await pushPreferencesToDrive(accessToken, useDeckStore.getState().preferences);
        const pendingDeletions = useDeckStore.getState().pendingDeletions;
        if (pendingDeletions.length > 0) {
          const deletedIds = await deleteDecksFromDrive(accessToken, pendingDeletions);
          if (deletedIds.length > 0) {
            removePendingDeletions(deletedIds);
          }
        }

        setLocalChanges(false);
        markSyncStatus("success");
        return true;
      } catch (error) {
        const message =
          error instanceof Error ? error.message : "Failed to push decks to Google Drive.";
        markSyncStatus("error", message);
        console.error(error);
        return false;
      }
    },
    [markSyncStatus, setDeckSyncMetadata, setLocalChanges, removePendingDeletions]
  );

  const resolveConflict = useCallback(
    async (deckId: string, resolution: "local" | "remote", accessToken: string) => {
      const state = useDeckStore.getState();
      const conflict = state.conflicts.find((item) => item.deckId === deckId);
      if (!conflict) {
        return;
      }

      markSyncStatus("syncing");
      try {
        if (resolution === "remote") {
          replaceDeck({
            ...conflict.remote,
            driveFileId: conflict.driveFileId,
            lastSyncedAt: conflict.remote.updatedAt
          });
          setDeckSyncMetadata(conflict.remote.id, {
            driveFileId: conflict.driveFileId,
            lastSyncedAt: conflict.remote.updatedAt
          });
        } else {
          const metadata = await uploadDeckToDrive({
            accessToken,
            deck: conflict.local
          });
          replaceDeck({
            ...conflict.local,
            driveFileId: metadata.driveFileId,
            lastSyncedAt: metadata.lastSyncedAt
          });
          setDeckSyncMetadata(conflict.local.id, metadata);
        }

        setConflicts(state.conflicts.filter((item) => item.deckId !== deckId));
        setLocalChanges(false);
        markSyncStatus("success");
      } catch (error) {
        const message =
          error instanceof Error ? error.message : "Failed to resolve conflict.";
        markSyncStatus("error", message);
        console.error(error);
      }
    },
    [replaceDeck, setDeckSyncMetadata, setConflicts, markSyncStatus, setLocalChanges]
  );

  const dismissConflicts = useCallback(() => {
    clearConflicts();
  }, [clearConflicts]);

  return {
    pullFromDrive,
    pushLocalChanges,
    resolveConflict,
    dismissConflicts,
    syncStatus,
    syncError,
    conflicts
  };
};
