import { create } from "zustand";
import { persist, createJSONStorage } from "zustand/middleware";
import { DeckRecord, deserializeDeck, serializeDeck, StoredDeckRecord } from "./types";
import { createCard, createDeckRecord } from "./helpers";
import { ReviewMode } from "../review/types";
import { Locale } from "../i18n/locales/types";
import { ThemePreference } from "../theme/types";
import { MatchResult } from "@core/models";

export type PendingDeckDeletion = {
  deckId: string;
  driveFileId: string;
};

export type DeckSyncMetadata = {
  driveFileId?: string;
  lastSyncedAt?: Date;
};

export type DeckSyncConflict = {
  deckId: string;
  driveFileId?: string;
  local: DeckRecord;
  remote: DeckRecord;
};

type DeckDraftCardInput = {
  id?: string;
  front: string;
  back: string;
  notes?: string;
};

export type AppPreferences = {
  locale: Locale;
  theme: ThemePreference;
};

type DeckStoreState = {
  decks: DeckRecord[];
  selectedDeckId: string | undefined;
  syncStatus: "idle" | "syncing" | "error" | "success";
  syncError: string | undefined;
  conflicts: DeckSyncConflict[];
  hasLocalChanges: boolean;
  preferences: AppPreferences;
  pendingDeletions: PendingDeckDeletion[];
  reviewState: Record<
    string,
    | {
        mode: ReviewMode;
        currentIndex: number;
        cardOrder: string[];
        round: number;
        unknownCardIds: string[];
        statusMap: Record<string, "known" | "unknown">;
        lastUpdatedAt: string;
      }
    | undefined
  >;
  createDeck: (payload: {
    title: string;
    description?: string;
    cards: Array<{ front: string; back: string; notes?: string }>;
  }) => string;
  addCardToDeck: (deckId: string, card: { front: string; back: string; notes?: string }) => void;
  removeCardFromDeck: (deckId: string, cardId: string) => void;
  updateDeckDetails: (
    deckId: string,
    payload: Partial<Pick<DeckRecord, "title" | "description">>
  ) => void;
  deleteDeck: (deckId: string) => void;
  setDeckSyncMetadata: (deckId: string, metadata: DeckSyncMetadata) => void;
  replaceDeck: (deck: DeckRecord) => void;
  updateDeckFromDraft: (
    deckId: string,
    payload: { title: string; description?: string; cards: DeckDraftCardInput[] }
  ) => void;
  setDeckReviewState: (
    deckId: string,
    state:
      | {
          mode: ReviewMode;
          currentIndex: number;
          cardOrder: string[];
          round: number;
          unknownCardIds: string[];
          statusMap?: Record<string, "known" | "unknown">;
          lastUpdatedAt?: Date;
        }
      | undefined
  ) => void;
  markSyncStatus: (status: DeckStoreState["syncStatus"], error?: string) => void;
  setConflicts: (conflicts: DeckSyncConflict[]) => void;
  clearConflicts: () => void;
  setLocalChanges: (flag: boolean) => void;
  setThemePreference: (theme: ThemePreference) => void;
  setLocalePreference: (locale: Locale) => void;
  setPreferences: (prefs: AppPreferences) => void;
  addMatchResult: (deckId: string, result: MatchResult) => void;
  removePendingDeletions: (deckIds: string[]) => void;
};

const STORAGE_KEY = "mova-nova-decks";

type PersistedState = {
  decks: StoredDeckRecord[];
  reviewState?: DeckStoreState["reviewState"];
  preferences?: AppPreferences;
  pendingDeletions?: PendingDeckDeletion[];
};

type DeckDataState = Pick<
  DeckStoreState,
  | "decks"
  | "selectedDeckId"
  | "syncStatus"
  | "syncError"
  | "conflicts"
  | "hasLocalChanges"
  | "preferences"
  | "pendingDeletions"
  | "reviewState"
>;

const defaultState: DeckDataState = {
  decks: [],
  selectedDeckId: undefined,
  syncStatus: "idle",
  syncError: undefined,
  conflicts: [],
  hasLocalChanges: false,
  pendingDeletions: [],
  preferences: {
    locale: "en",
    theme: "system"
  },
  reviewState: {}
};

export const useDeckStore = create<DeckStoreState>()(
  persist(
    (set, get) => ({
      ...defaultState,
      createDeck: ({ title, description, cards }) => {
        const deck = createDeckRecord({
          title,
          ...(description ? { description } : {}),
          cards
        });
        set((state) => ({
          decks: [...state.decks, deck],
          selectedDeckId: deck.id,
          syncStatus: "idle",
          syncError: undefined,
          hasLocalChanges: true,
          reviewState: {
            ...state.reviewState,
            [deck.id]: undefined
          }
        }));
        return deck.id;
      },
      addCardToDeck: (deckId, payload) =>
        set((state) => {
          const deck = state.decks.find((item) => item.id === deckId);
          if (!deck) {
            return state;
          }
          const card = createCard({ deckId, ...payload });
          const updatedDeck: DeckRecord = {
            ...deck,
            cards: [...deck.cards, card],
            updatedAt: new Date(),
            version: deck.version + 1
          };
          return {
            ...state,
            decks: state.decks.map((item) => (item.id === deckId ? updatedDeck : item)),
            hasLocalChanges: true,
            reviewState: {
              ...state.reviewState,
              [deckId]: undefined
            }
          };
        }),
      removeCardFromDeck: (deckId, cardId) =>
        set((state) => {
          const deck = state.decks.find((item) => item.id === deckId);
          if (!deck) {
            return state;
          }
          const updatedDeck: DeckRecord = {
            ...deck,
            cards: deck.cards.filter((card) => card.id !== cardId),
            updatedAt: new Date(),
            version: deck.version + 1
          };
          return {
            ...state,
            decks: state.decks.map((item) => (item.id === deckId ? updatedDeck : item)),
            hasLocalChanges: true,
            reviewState: {
              ...state.reviewState,
              [deckId]: undefined
            }
          };
        }),
      updateDeckDetails: (deckId, payload) =>
        set((state) => {
          const deck = state.decks.find((item) => item.id === deckId);
          if (!deck) {
            return state;
          }
          const updatedDeck: DeckRecord = {
            ...deck,
            ...payload,
            updatedAt: new Date(),
            version: deck.version + 1
          };
          return {
            ...state,
            decks: state.decks.map((item) => (item.id === deckId ? updatedDeck : item)),
            hasLocalChanges: true,
            reviewState: {
              ...state.reviewState,
              [deckId]: undefined
            }
          };
        }),
      deleteDeck: (deckId) =>
        set((state) => {
          const deck = state.decks.find((item) => item.id === deckId);
          if (!deck) {
            return state;
          }
          const filteredPending = state.pendingDeletions.filter((item) => item.deckId !== deckId);
          const pendingDeletions =
            deck.driveFileId != null
              ? [...filteredPending, { deckId, driveFileId: deck.driveFileId }]
              : filteredPending;
          return {
            ...state,
            decks: state.decks.filter((item) => item.id !== deckId),
            selectedDeckId: state.selectedDeckId === deckId ? undefined : state.selectedDeckId,
            hasLocalChanges: true,
            pendingDeletions,
            reviewState: Object.fromEntries(
              Object.entries(state.reviewState).filter(([id]) => id !== deckId)
            )
          };
        }),
      setDeckSyncMetadata: (deckId, metadata) =>
        set((state) => {
          const deck = state.decks.find((item) => item.id === deckId);
          if (!deck) {
            return state;
          }
          const updatedDeck: DeckRecord = {
            ...deck,
            driveFileId: metadata.driveFileId ?? deck.driveFileId,
            lastSyncedAt: metadata.lastSyncedAt ?? deck.lastSyncedAt
          };
          return {
            ...state,
            decks: state.decks.map((item) => (item.id === deckId ? updatedDeck : item))
          };
        }),
      replaceDeck: (deck) =>
        set((state) => {
          const existing = state.decks.find((item) => item.id === deck.id);
          const decks = existing
            ? state.decks.map((item) => (item.id === deck.id ? deck : item))
            : [...state.decks, deck];

          let reviewState = state.reviewState;
          if (existing) {
            const keepReview =
              state.reviewState[deck.id] &&
              existing.cards.length === deck.cards.length &&
              existing.updatedAt.getTime() === deck.updatedAt.getTime();
            if (!keepReview) {
              reviewState = {
                ...state.reviewState,
                [deck.id]: undefined
              };
            }
          }

          return {
            ...state,
            decks,
            reviewState
          };
        }),
      updateDeckFromDraft: (deckId, payload) =>
        set((state) => {
          const deck = state.decks.find((item) => item.id === deckId);
          if (!deck) {
            return state;
          }

          const now = new Date();
          const existingCards = new Map(deck.cards.map((card) => [card.id, card]));

          const cards = payload.cards.map((cardInput) => {
            if (cardInput.id && existingCards.has(cardInput.id)) {
              const existing = existingCards.get(cardInput.id)!;
              return {
                ...existing,
                front: cardInput.front,
                back: cardInput.back,
                notes: cardInput.notes,
                updatedAt: now
              };
            }
            return createCard({
              deckId,
              front: cardInput.front,
              back: cardInput.back,
              ...(cardInput.notes ? { notes: cardInput.notes } : {})
            });
          });

          const dueCardCount = cards.reduce(
            (count, card) => (card.dueAt.getTime() <= now.getTime() ? count + 1 : count),
            0
          );

          const updatedDeck: DeckRecord = {
            ...deck,
            title: payload.title,
            description: payload.description,
            cards,
            updatedAt: now,
            version: deck.version + 1,
            dueCardCount,
            lastSyncedAt: deck.lastSyncedAt
          };

          return {
            ...state,
            decks: state.decks.map((item) => (item.id === deckId ? updatedDeck : item)),
            hasLocalChanges: true,
            reviewState: {
              ...state.reviewState,
              [deckId]: undefined
            }
          };
        }),
      setDeckReviewState: (deckId, reviewState) =>
        set((state) => ({
          ...state,
          reviewState: {
            ...state.reviewState,
            [deckId]: reviewState
              ? {
                  ...reviewState,
                  statusMap: reviewState.statusMap ?? {},
                  lastUpdatedAt: (reviewState.lastUpdatedAt ?? new Date()).toISOString()
                }
              : undefined
          }
        })),
      markSyncStatus: (status, error) =>
        set(() => ({
          syncStatus: status,
          syncError: error
        })),
      setConflicts: (conflicts) =>
        set(() => ({
          conflicts
        })),
      clearConflicts: () =>
        set(() => ({
          conflicts: []
        })),
      setLocalChanges: (flag) =>
        set((state) => ({
          hasLocalChanges: flag ? true : state.pendingDeletions.length > 0 ? true : false
        })),
      setThemePreference: (theme) =>
        set((state) => ({
          ...state,
          preferences: {
            ...state.preferences,
            theme
          },
          hasLocalChanges: true
        })),
      setLocalePreference: (locale) =>
        set((state) => ({
          ...state,
          preferences: {
            ...state.preferences,
            locale
          },
          hasLocalChanges: true
        })),
      setPreferences: (preferences) =>
        set((state) => ({
          ...state,
          preferences
        })),
      addMatchResult: (deckId, result) =>
        set((state) => {
          const deck = state.decks.find((d) => d.id === deckId);
          if (!deck) {
            return state;
          }
          const updatedDeck: DeckRecord = {
            ...deck,
            matchResults: [...(deck.matchResults ?? []), result],
            updatedAt: new Date(),
            version: deck.version + 1
          };
          return {
            ...state,
            decks: state.decks.map((d) => (d.id === deckId ? updatedDeck : d)),
            hasLocalChanges: true
          };
        }),
      removePendingDeletions: (deckIds) =>
        set((state) => ({
          ...state,
          pendingDeletions: state.pendingDeletions.filter(
            (item) => !deckIds.includes(item.deckId)
          )
        }))
    }),
    {
      name: STORAGE_KEY,
      storage:
        typeof window !== "undefined"
          ? createJSONStorage(() => window.localStorage)
          : undefined,
      version: 1,
      partialize: (state) => ({
        decks: state.decks.map(serializeDeck),
        reviewState: state.reviewState,
        preferences: state.preferences,
        pendingDeletions: state.pendingDeletions
      }),
      merge: (persistedState, currentState) => {
        const data = persistedState as PersistedState | undefined;
        if (!data?.decks) {
          return currentState;
        }

        const decks = data.decks.map(deserializeDeck);
        const reviewState = data.reviewState ?? {};

        const sanitizedReviewState: DeckStoreState["reviewState"] = {};
        decks.forEach((deck) => {
          const state = reviewState[deck.id];
          if (!state || !state.mode) {
            return;
          }
          const cardIds = new Set(deck.cards.map((card) => card.id));
          const isValid =
            state.cardOrder.every((cardId) => cardIds.has(cardId)) &&
            state.unknownCardIds.every((cardId) => cardIds.has(cardId));
          if (isValid) {
            sanitizedReviewState[deck.id] = {
              ...state,
              statusMap: state.statusMap ?? {}
            };
          }
        });

        const hasLocalChanges = decks.some((deck) => {
          if (!deck.lastSyncedAt) {
            return true;
          }
          return deck.updatedAt.getTime() > deck.lastSyncedAt.getTime();
        });

        return {
          ...currentState,
          decks,
          reviewState: sanitizedReviewState,
          hasLocalChanges,
          preferences: data.preferences ?? currentState.preferences,
          pendingDeletions: data.pendingDeletions ?? currentState.pendingDeletions
        };
      }
    }
  )
);
