import { FormEvent, useEffect, useMemo, useState } from "react";
import clsx from "clsx";
import { nanoid } from "nanoid";
import { Button } from "@ui/components/Button";
import { GlassModal } from "@ui/components/GlassModal";
import { useTranslation } from "../i18n/I18nProvider";
import { parseBulkInput } from "./helpers";
import { useDeckStore } from "./useDeckStore";
import { DeckRecord } from "./types";
import { FormLabel, HelpText, FormGroup, TextInput, TextArea, CardPanel } from "@ui/components/Form";

type Mode = "create" | "edit";

type DraftCard = {
  id?: string;
  tempId: string;
  front: string;
  back: string;
  notes?: string;
};

type DeckFormModalProps = {
  isOpen: boolean;
  mode: Mode;
  deck?: DeckRecord;
  onClose: () => void;
};

const toDraftCard = (card: DraftCard | DeckRecord["cards"][number]): DraftCard => {
  if ("tempId" in card) {
    return card;
  }
  return {
    id: card.id,
    tempId: card.id,
    front: card.front,
    back: card.back,
    ...(card.notes != null ? { notes: card.notes } : {})
  };
};

const INITIAL_CARD: DraftCard = {
  tempId: nanoid(),
  front: "",
  back: ""
};


export const DeckFormModal = ({ isOpen, mode, deck, onClose }: DeckFormModalProps) => {
  const { t } = useTranslation();
  const createDeck = useDeckStore((state) => state.createDeck);
  const updateDeckFromDraft = useDeckStore((state) => state.updateDeckFromDraft);

  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [draftCards, setDraftCards] = useState<DraftCard[]>([]);
  const [bulkInput, setBulkInput] = useState("");
  const [bulkDelimiter, setBulkDelimiter] = useState(",");
  const [manualCard, setManualCard] = useState<DraftCard>(INITIAL_CARD);
  const [error, setError] = useState<string>();

  useEffect(() => {
    if (isOpen && mode === "edit" && !deck) {
      onClose();
    }
  }, [isOpen, mode, deck, onClose]);

  useEffect(() => {
    if (!isOpen) {
      return;
    }

    if (mode === "edit") {
      if (!deck) {
        // Wait until the deck is loaded to avoid clearing existing draft state.
        return;
      }
      setTitle(deck.title);
      setDescription(deck.description ?? "");
      setDraftCards(deck.cards.map((card) => toDraftCard(card)));
    } else {
      // Create mode: initialize empty state.
      setTitle("");
      setDescription("");
      setDraftCards([]);
    }
    setBulkInput("");
    setBulkDelimiter(",");
    setManualCard({ ...INITIAL_CARD, tempId: nanoid() });
    setError(undefined);
  }, [isOpen, mode, deck]);

  const heading = mode === "create" ? t("deck.modalCreateTitle") : t("deck.modalEditTitle");
  const primaryActionLabel = mode === "create" ? t("deck.createDeck") : t("deck.saveChanges");
  const hasCards = draftCards.length > 0;

  const cardsReadyLabel = useMemo(() => {
    if (!hasCards) {
      return undefined;
    }
    return t("deck.cardsReady", { count: draftCards.length });
  }, [hasCards, draftCards.length, t]);

  const handleAddParsedCards = () => {
    const parsed = parseBulkInput(bulkInput, bulkDelimiter);
    if (parsed.length === 0) {
      setError(t("deck.validationCards"));
      return;
    }
    setDraftCards((prev) => [
      ...prev,
      ...parsed.map((item) => ({
        tempId: nanoid(),
        front: item.front,
        back: item.back
      }))
    ]);
    setBulkInput("");
    setError(undefined);
  };

  const handleAddManualCard = () => {
    if (!manualCard.front.trim() || !manualCard.back.trim()) {
      setError(t("deck.validationCards"));
      return;
    }
    setDraftCards((prev) => [
      ...prev,
      {
        tempId: manualCard.tempId,
        front: manualCard.front.trim(),
        back: manualCard.back.trim()
      }
    ]);
    setManualCard({ ...INITIAL_CARD, tempId: nanoid() });
    setError(undefined);
  };

  const handleCardFieldChange = (tempId: string, field: "front" | "back", value: string) => {
    setDraftCards((prev) =>
      prev.map((card) => (card.tempId === tempId ? { ...card, [field]: value } : card))
    );
  };

  const handleRemoveCard = (tempId: string) => {
    setDraftCards((prev) => prev.filter((card) => card.tempId !== tempId));
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!title.trim()) {
      setError(t("deck.validationTitle"));
      return;
    }
    if (!hasCards) {
      setError(t("deck.validationCards"));
      return;
    }

    const cards = draftCards.map((card) => ({
      ...(card.id != null ? { id: card.id } : {}),
      front: card.front.trim(),
      back: card.back.trim(),
      ...(card.notes != null ? { notes: card.notes } : {})
    }));

    if (cards.some((card) => !card.front || !card.back)) {
      setError(t("deck.validationCards"));
      return;
    }

    if (mode === "create") {
      createDeck({
        title: title.trim(),
        ...(description.trim() ? { description: description.trim() } : {}),
        cards: cards.map(({ front, back, notes }) => ({
          front,
          back,
          ...(notes != null ? { notes } : {})
        }))
      });
    } else if (mode === "edit" && deck) {
      updateDeckFromDraft(deck.id, {
        title: title.trim(),
        ...(description.trim() ? { description: description.trim() } : {}),
        cards
      });
    }

    onClose();
  };

  return (
    <GlassModal open={isOpen} onClose={onClose} contentClassName="text-slate-900 dark:text-slate-50">
        <form
          onSubmit={handleSubmit}
          className="ui-form"
        >
        <header className="ui-form-header">
          <div>
            <h3 className="ui-form-title">{heading}</h3>
            <p className="ui-form-subtitle">{t("deck.modalSubtitle")}</p>
          </div>
        </header>

        <div className="ui-grid-md-2">
          <div className="ui-col">
            <FormGroup>
              <FormLabel htmlFor="deck-modal-title">
                {t("deck.formTitleLabel")}
              </FormLabel>
              <TextInput
                id="deck-modal-title"
                value={title}
                onChange={(event) => setTitle(event.target.value)}
                placeholder={t("deck.formTitlePlaceholder")}
              />
            </FormGroup>

            <FormGroup>
              <FormLabel htmlFor="deck-modal-description">
                {t("deck.formDescriptionLabel")}
              </FormLabel>
              <TextArea
                id="deck-modal-description"
                value={description}
                onChange={(event) => setDescription(event.target.value)}
                placeholder={t("deck.formDescriptionPlaceholder")}
                rows={3}
                resize="none"
              />
            </FormGroup>

            <FormGroup>
              <div className="flex flex-wrap items-center justify-between gap-3">
                <FormLabel htmlFor="deck-bulk-input">
                  {t("deck.bulkImportLabel")}
                </FormLabel>
                <div className="ui-delimiter-bar">
                  <span>{t("deck.bulkDelimiterLabel")}</span>
                  <TextInput
                    uiSize="sm"
                    value={bulkDelimiter}
                    onChange={(event) => setBulkDelimiter(event.target.value)}
                    placeholder={t("deck.bulkDelimiterPlaceholder")}
                    className="w-20"
                  />
                  <div className="ui-chip-list">
                    {[
                      { label: "::", value: "::" },
                      { label: t("deck.bulkDelimiterTab"), value: "\\t" },
                      { label: ";", value: ";" },
                      { label: ",", value: "," }
                    ].map((preset) => (
                      <button
                        key={preset.value}
                        type="button"
                        className={clsx("ui-chip", bulkDelimiter === preset.value && "is-active")}
                        onClick={() => setBulkDelimiter(preset.value)}
                      >
                        {preset.label}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
              <TextArea
                id="deck-bulk-input"
                value={bulkInput}
                onChange={(event) => setBulkInput(event.target.value)}
                placeholder={t("deck.bulkImportPlaceholder")}
                className="min-h-[16rem] border-dashed"
              />
              <HelpText>
                {t("deck.bulkImportHint")}
              </HelpText>
              <Button type="button" size="sm" variant="secondary" onClick={handleAddParsedCards}>
                {t("deck.addParsedCards")}
              </Button>
            </FormGroup>

            <FormGroup>
              <p className="ui-form-label">
                {t("deck.manualAddLabel")}
              </p>
              <div className="grid gap-2 md:grid-cols-2">
                <TextInput
                  value={manualCard.front}
                  onChange={(event) =>
                    setManualCard((prev) => ({ ...prev, front: event.target.value }))
                  }
                  placeholder={t("deck.manualFrontPlaceholder")}
                />
                <TextInput
                  value={manualCard.back}
                  onChange={(event) =>
                    setManualCard((prev) => ({ ...prev, back: event.target.value }))
                  }
                  placeholder={t("deck.manualBackPlaceholder")}
                />
              </div>
            </FormGroup>
              <Button type="button" size="sm" variant="secondary" onClick={handleAddManualCard}>
                {t("deck.addCard")}
              </Button>
          </div>

          <div className="ui-col">
            <div className="ui-row-between">
              <h4 className="ui-form-label">
                {t("deck.cardEditorLabel")}
              </h4>
              {cardsReadyLabel && (
                <span className="ui-muted">{cardsReadyLabel}</span>
              )}
            </div>
            <div className="ui-list pr-1">
              {draftCards.length === 0 ? (
                <p className="ui-muted">
                  {t("deck.cardListEmpty")}
                </p>
              ) : (
                draftCards.map((card, index) => (
                  <CardPanel key={card.tempId}>
                    <div className="flex items-center justify-between text-slate-500 dark:text-slate-400">
                      <span>
                        {t("deck.cardLabel")} {index + 1}
                      </span>
                      <button
                        type="button"
                        onClick={() => handleRemoveCard(card.tempId)}
                        className="text-xs font-medium text-red-300 transition hover:text-red-200"
                      >
                        {t("deck.removeCard")}
                      </button>
                    </div>
                    <div className="mt-3 space-y-2">
                      <TextArea
                        value={card.front}
                        onChange={(event) =>
                          handleCardFieldChange(card.tempId, "front", event.target.value)
                        }
                        placeholder={t("deck.manualFrontPlaceholder")}
                        rows={2}
                        className="min-h-[3.5rem]"
                        resize="none"
                      />
                      <TextArea
                        value={card.back}
                        onChange={(event) =>
                          handleCardFieldChange(card.tempId, "back", event.target.value)
                        }
                        placeholder={t("deck.manualBackPlaceholder")}
                        rows={2}
                        className="min-h-[3.5rem]"
                        resize="none"
                      />
                    </div>
                  </CardPanel>
                ))
              )}
          </div>
        </div>
        </div>

        {error && (
          <p className="ui-error">
            {error}
          </p>
        )}

        <footer className="ui-form-footer">
          <div className="ui-actions-right">
            <Button type="button" variant="secondary" onClick={onClose}>
              {t("deck.cancel")}
            </Button>
            <Button
              type="submit"
              variant="secondary"
              className="ui-btn-emerald-soft"
              disabled={!title.trim() || !hasCards}
            >
              {primaryActionLabel}
            </Button>
          </div>
        </footer>
      </form>
    </GlassModal>
  );
};

