import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import clsx from "clsx";
import { GlassModal } from "@ui/components/GlassModal";
import { Button } from "@ui/components/Button";
import { useGrowl } from "@ui/components/Growl";
import { TypeIcon } from "../components/icons";
import { useTranslation } from "../i18n/I18nProvider";
import { useDeckReview } from "./useDeckReview";
import type { ReviewOrientation } from "./types";
import { ReviewStats } from "./ReviewStats";

type TypeReviewModalProps = {
  deckId?: string;
  isOpen: boolean;
  onClose: () => void;
  minCardsRequired: number;
};

type FlashOrderMode = "start" | "end" | "random";

const normalize = (value: string) => value.trim().toLowerCase();

export const TypeReviewModal = ({
  deckId,
  isOpen,
  onClose,
  minCardsRequired
}: TypeReviewModalProps) => {
  const { t } = useTranslation();
  const { showGrowl } = useGrowl();
  const [orientation, setOrientation] = useState<ReviewOrientation>("front-first");
  const [orderMode, setOrderMode] = useState<FlashOrderMode>("random");
  const [limitInput, setLimitInput] = useState("10");
  const [sessionVersion, setSessionVersion] = useState(0);
  const [answer, setAnswer] = useState("");

  const limitValue = limitInput ? Math.max(1, parseInt(limitInput, 10) || 0) : undefined;
  const typeReview = useDeckReview(deckId, "type", orientation, {
    orderMode,
    limit: limitValue
  });

  const {
    deck,
    reviewState,
    currentCard,
    totalKnown,
    totalUnknown,
    startNewSession,
    startUnknownRound,
    markCardAsKnown,
    markCardAsUnknown,
    resetProgress
  } = typeReview;
  const hasCards = Boolean(deck && deck.cards.length > 0);
  const hasEnough = Boolean(deck && deck.cards.length >= minCardsRequired);
  const inProgress =
    reviewState != null &&
    reviewState.currentIndex < reviewState.cardOrder.length &&
    currentCard != null;
  const isSummary =
    reviewState != null && reviewState.currentIndex >= reviewState.cardOrder.length && hasCards;
  const nextRoundUnknownCount = reviewState?.unknownCardIds.length ?? 0;
  const canReviewUnknown = nextRoundUnknownCount > 0;

  const progressLabel = useMemo(() => {
    if (!reviewState || !currentCard) {
      return undefined;
    }
    return t("review.progress", {
      current: reviewState.currentIndex + 1,
      total: reviewState.cardOrder.length
    });
  }, [reviewState, currentCard, t]);

  const resetSession = useCallback(() => {
    setSessionVersion(0);
    setAnswer("");
    resetProgress();
  }, [resetProgress]);

  useEffect(() => {
    if (!isOpen) {
      resetSession();
    }
  }, [isOpen, resetSession]);

  useEffect(() => {
    setAnswer("");
  }, [currentCard?.id]);

  useEffect(() => {
    if (!isOpen || !hasCards || sessionVersion === 0) return;
    resetProgress();
    startNewSession();
    setAnswer("");
  }, [isOpen, hasCards, sessionVersion, resetProgress, startNewSession]);

  const startSession = useCallback(() => {
    if (!hasCards || !hasEnough) return;
    setSessionVersion((prev) => prev + 1);
  }, [hasCards, hasEnough]);

  const handleOrderChange = useCallback(
    (value: FlashOrderMode) => {
      if (value === orderMode) return;
      setOrderMode(value);
      resetSession();
    },
    [orderMode, resetSession]
  );

  const handleOrientationChange = useCallback(
    (value: ReviewOrientation) => {
      if (value === orientation) return;
      setOrientation(value);
      resetSession();
    },
    [orientation, resetSession]
  );

  const handleLimitChange = useCallback((value: string) => {
    const sanitized = value.replace(/[^\d]/g, "");
    setLimitInput(sanitized);
    resetSession();
  }, [resetSession]);

  const promptLabel = orientation === "front-first" ? t("review.cardFront") : t("review.cardBack");
  const typedAnswerLabel = orientation === "front-first" ? t("review.cardBack") : t("review.cardFront");

  const handleSubmit = useCallback(
    (event: React.FormEvent) => {
      event.preventDefault();
      if (!currentCard) return;
      if (!answer.trim()) {
        showGrowl({ tone: "warning", message: t("review.type.empty") });
        return;
      }
      const expected = normalize(currentCard.back);
      const userValue = normalize(answer);
      const isCorrect = expected === userValue;
      if (isCorrect) {
        markCardAsKnown();
        showGrowl({ tone: "success", message: t("review.type.correct") });
      } else {
        markCardAsUnknown();
        showGrowl({
          tone: "warning",
          message: t("review.type.incorrect", { answer: currentCard.back })
        });
      }
      setAnswer("");
    },
    [answer, currentCard, t, markCardAsKnown, markCardAsUnknown, showGrowl]
  );

  return (
    <GlassModal open={isOpen} onClose={onClose} panelClassName="max-w-4xl" contentClassName="text-slate-900 dark:text-slate-50">
      <header className="flex flex-wrap items-start justify-between gap-3 md:gap-4">
        <div className="space-y-2">
          <p className="flex items-center gap-2 text-xs uppercase tracking-wide text-brand-400">
            <span className="text-brand-500">
              <TypeIcon className="h-4 w-4" />
            </span>
            {t("review.mode.typeLabel")}
          </p>
          <h2 className="text-xl md:text-2xl font-semibold text-slate-900 dark:text-slate-50">
            {deck ? deck.title : t("review.selectDeck")}
          </h2>
          {deck?.description && (
            <p className="hidden md:block text-sm text-slate-700 dark:text-slate-400">{deck.description}</p>
          )}
          <p className="hidden md:block text-sm text-slate-700 dark:text-slate-500">{t("review.startDescription")}</p>
          {progressLabel && (
            <p className="text-xs font-semibold uppercase tracking-wide text-brand-500">
              {progressLabel}
            </p>
          )}
        </div>
      </header>

      <div className="ui-card-panel text-sm ui-vstack-3">
        <div className="ui-flash-settings-grid">
          <div className="ui-flash-settings-section">
            <span className="ui-kicker">
              {t("review.flash.orderLabel")}
            </span>
            <div className="ui-flash-toggle-row">
              {(["start", "end", "random"] as FlashOrderMode[]).map((option) => {
                const active = orderMode === option;
                return (
                  <Button
                    key={option}
                    size="sm"
                    variant={active ? "secondary" : "outline"}
                    className={clsx(active && "ui-btn-emerald-soft")}
                    onClick={() => handleOrderChange(option)}
                  >
                    {t(
                      option === "start"
                        ? "review.flash.orderStart"
                        : option === "end"
                        ? "review.flash.orderEnd"
                        : "review.flash.orderRandom"
                    )}
                  </Button>
                );
              })}
            </div>
          </div>
          <div className="ui-flash-settings-section">
            <span className="ui-kicker">
              {t("review.flash.orientationLabel")}
            </span>
            <div className="ui-flash-toggle-row">
              <Button
                size="sm"
                variant={orientation === "front-first" ? "secondary" : "outline"}
                className={clsx("ui-nowrap", orientation === "front-first" && "ui-btn-emerald-soft")}
                onClick={() => handleOrientationChange("front-first")}
              >
                {t("review.cardFront")} ↦ {t("review.cardBack")}
              </Button>
              <Button
                size="sm"
                variant={orientation === "back-first" ? "secondary" : "outline"}
                className={clsx("ui-nowrap", orientation === "back-first" && "ui-btn-emerald-soft")}
                onClick={() => handleOrientationChange("back-first")}
              >
                {t("review.cardBack")} ↦ {t("review.cardFront")}
              </Button>
            </div>
          </div>
        </div>
        <label className="flex flex-col gap-1 text-xs">
          <span className="uppercase tracking-wide text-slate-500 dark:text-slate-400">
            {t("review.learn.limitLabel")}
          </span>
          <input
            type="number"
            min={1}
            inputMode="numeric"
            className="ui-input"
            value={limitInput}
            onChange={(event) => handleLimitChange(event.target.value)}
            placeholder={t("review.learn.limitPlaceholder")}
          />
        </label>
        <div className="ui-flash-action-row">
          <Button
            size="sm"
            variant="secondary"
            className="ui-btn-emerald-soft"
            onClick={startSession}
            disabled={!hasCards || !hasEnough}
          >
            {sessionVersion > 0 ? t("review.flash.restartButton") : t("review.type.startButton")}
          </Button>
        </div>
      </div>

      {!hasCards && (
        <div className="ui-empty-panel">
          {t("review.emptyDeck")}
        </div>
      )}
      {hasCards && !hasEnough && (
        <div className="ui-empty-panel">
          {t("review.minCardsRequired", { count: minCardsRequired })}
        </div>
      )}

      {hasCards && hasEnough && sessionVersion === 0 && (
        <div className="ui-empty-panel">
          {t("review.type.waiting")}
        </div>
      )}

      {hasCards && hasEnough && inProgress && currentCard && (
        <form className="ui-vstack-3" onSubmit={handleSubmit}>
          <div className="ui-card-panel text-sm space-y-4">
            <div className="space-y-2">
              <span className="ui-kicker">
                {promptLabel}
              </span>
              <p className="ui-prewrap ui-title-2xl">
                {currentCard.front}
              </p>
            </div>
            <label className="flex flex-col gap-2 text-xs">
              <span className="uppercase tracking-wide text-slate-500 dark:text-slate-400">
                {t("review.type.prompt", { label: typedAnswerLabel })}
              </span>
              <input
                type="text"
                className="ui-input"
                value={answer}
                onChange={(event) => setAnswer(event.target.value)}
                placeholder={t("review.type.placeholder")}
                autoFocus
              />
            </label>
            <Button type="submit" variant="primary" size="sm" disabled={!answer.trim()}>
              {t("review.type.submit")}
            </Button>
          </div>
        </form>
      )}

      {hasCards && hasEnough && isSummary && reviewState && (
        <ReviewStats
          totalCards={totalKnown + totalUnknown}
          knownCards={totalKnown}
          unknownCards={totalUnknown}
          round={reviewState.round}
          nextRoundUnknown={nextRoundUnknownCount}
          onRestartUnknown={() => {
            if (canReviewUnknown) {
              startUnknownRound();
            }
          }}
        />
      )}
    </GlassModal>
  );
};
