import { forwardRef } from "react";
import clsx from "clsx";

/**
 * Form primitives using global CSS classes to reduce inline Tailwind usage.
 * Classes are defined in apps/web/src/styles/global.css under @layer components.
 * - TextInput / TextArea: base styles via .ui-input / .ui-textarea
 * - FormLabel / HelpText / FormGroup: typography + spacing
 * - CardPanel: inline editor container
 */

export type UIInputSize = "md" | "sm";

type TextInputProps = Omit<React.InputHTMLAttributes<HTMLInputElement>, "size"> & {
  uiSize?: UIInputSize;
  htmlSize?: number;
};

export const TextInput = forwardRef<HTMLInputElement, TextInputProps>(
  ({ className, uiSize = "md", htmlSize, ...props }, ref) => (
    <input
      ref={ref}
      size={htmlSize}
      className={clsx("ui-input", uiSize === "sm" && "ui-input-sm", className)}
      {...props}
    />
  )
);

TextInput.displayName = "TextInput";

type TextAreaResize = "none" | "y" | "both";

type TextAreaProps = React.TextareaHTMLAttributes<HTMLTextAreaElement> & {
  resize?: TextAreaResize;
};

export const TextArea = forwardRef<HTMLTextAreaElement, TextAreaProps>(
  ({ className, resize = "none", ...props }, ref) => (
    <textarea
      ref={ref}
      className={clsx(
        "ui-textarea",
        resize === "y" && "ui-textarea-resize-y",
        resize === "both" && "ui-textarea-resize-both",
        className
      )}
      {...props}
    />
  )
);

TextArea.displayName = "TextArea";

type FormLabelProps = React.LabelHTMLAttributes<HTMLLabelElement>;
export const FormLabel = ({ className, ...props }: FormLabelProps) => (
  <label className={clsx("ui-form-label", className)} {...props} />
);

type HelpTextProps = React.HTMLAttributes<HTMLParagraphElement>;
export const HelpText = ({ className, ...props }: HelpTextProps) => (
  <p className={clsx("ui-help-text", className)} {...props} />
);

type FormGroupProps = React.HTMLAttributes<HTMLDivElement>;
export const FormGroup = ({ className, ...props }: FormGroupProps) => (
  <div className={clsx("ui-form-group", className)} {...props} />
);

type CardPanelProps = React.HTMLAttributes<HTMLDivElement>;
export const CardPanel = forwardRef<HTMLDivElement, CardPanelProps>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={clsx("ui-card-panel", className)} {...props} />
  )
);

CardPanel.displayName = "CardPanel";