import { ReactNode } from "react";
import clsx from "clsx";
import { GlassPanel } from "./GlassPanel";

type GlassModalProps = {
  open: boolean;
  onClose: () => void;
  children: ReactNode;
  className?: string;
  overlayClassName?: string;
  panelClassName?: string;
  closeOnOverlay?: boolean;
  contentClassName?: string;
  showCloseButton?: boolean;
  closeAriaLabel?: string;
  closeButtonClassName?: string;
};

export const GlassModal = ({
  open,
  onClose,
  children,
  className,
  overlayClassName,
  panelClassName,
  closeOnOverlay = true,
  contentClassName,
  showCloseButton = true,
  closeAriaLabel,
  closeButtonClassName
}: GlassModalProps) => {
  if (!open) {
    return null;
  }

  const handleOverlayClick = () => {
    if (closeOnOverlay) {
      onClose();
    }
  };

  const stopPropagation = (event: React.MouseEvent) => {
    event.stopPropagation();
  };

  return (
    <div
      className={clsx(
        "fixed inset-0 z-[999] flex items-stretch justify-center overflow-hidden bg-slate-900/40 px-0 py-0 backdrop-blur-sm dark:bg-slate-950/80 md:items-start md:px-0 md:py-8",
        overlayClassName,
        className
      )}
      onClick={handleOverlayClick}
    >
      <GlassPanel
        className={clsx(
          "relative flex h-[100dvh] w-full flex-col overflow-hidden rounded-none p-0 md:h-[calc(100dvh-4rem)] md:max-w-4xl md:rounded-3xl md:p-2",
          panelClassName
        )}
        onClick={stopPropagation}
      >
        {showCloseButton && (
          <button
            type="button"
            aria-label={closeAriaLabel ?? "Close"}
            onClick={onClose}
            style={{
              top: "max(0.75rem, env(safe-area-inset-top))",
              right: "max(0.5rem, env(safe-area-inset-right))"
            }}
            className={clsx(
              "absolute right-2 top-3 z-20 rounded-full border border-slate-200 bg-white/80 p-2 text-slate-600 shadow-sm transition hover:border-slate-400 hover:text-slate-900 dark:border-white/15 dark:bg-white/10 dark:text-slate-300",
              closeButtonClassName
            )}
          >
            <svg
              className="h-5 w-5 md:h-4 md:w-4"
              viewBox="0 0 20 20"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
            >
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 6l8 8M14 6l-8 8" />
            </svg>
            <span className="sr-only">{closeAriaLabel ?? "Close"}</span>
          </button>
        )}
        <div
          className={clsx(
            "flex h-full w-full flex-1 min-h-0 flex-col gap-3 overflow-auto overscroll-contain px-0 py-1 pt-8 md:px-1 md:py-5",
            contentClassName
          )}
        >
          {children}
        </div>
      </GlassPanel>
    </div>
  );
};
