import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import clsx from "clsx";
import { GlassModal } from "@ui/components/GlassModal";
import { Button } from "@ui/components/Button";
import { FlashcardsIcon } from "../components/icons";
import { useTranslation } from "../i18n/I18nProvider";
import { useDeckReview } from "./useDeckReview";
import type { ReviewOrientation } from "./types";
import { ReviewCard } from "./ReviewCard";
import { ReviewStats } from "./ReviewStats";

type FlashcardsReviewModalProps = {
  deckId?: string;
  isOpen: boolean;
  onClose: () => void;
};

type FlashOrderMode = "start" | "end" | "random";

export const FlashcardsReviewModal = ({ deckId, isOpen, onClose }: FlashcardsReviewModalProps) => {
  const { t } = useTranslation();
  const [orientation, setOrientation] = useState<ReviewOrientation>("front-first");
  const [flashOrder, setFlashOrder] = useState<FlashOrderMode>("random");
  const [flashSessionVersion, setFlashSessionVersion] = useState(0);

  const flash = useDeckReview(deckId, "flashcards", orientation, { orderMode: flashOrder });
  const deck = flash.deck;
  const reviewState = flash.reviewState;
  const currentCard = flash.currentCard;
  const totalKnown = flash.totalKnown;
  const totalUnknown = flash.totalUnknown;
  const startUnknownRound = flash.startUnknownRound;

  const hasCards = Boolean(deck && deck.cards.length > 0);
  const isSummary =
    reviewState != null && reviewState.currentIndex >= reviewState.cardOrder.length && hasCards;
  const inProgress =
    reviewState != null &&
    reviewState.currentIndex < reviewState.cardOrder.length &&
    currentCard != null;
  const nextRoundUnknownCount = reviewState?.unknownCardIds.length ?? 0;
  const canReviewUnknown = nextRoundUnknownCount > 0;

  const progressLabel = useMemo(() => {
    if (!reviewState || !currentCard) {
      return undefined;
    }
    return t("review.progress", {
      current: reviewState.currentIndex + 1,
      total: reviewState.cardOrder.length
    });
  }, [reviewState, currentCard, t]);

  const flashOrderOptions = useMemo(
    () => [
      { value: "start" as FlashOrderMode, label: t("review.flash.orderStart") },
      { value: "end" as FlashOrderMode, label: t("review.flash.orderEnd") },
      { value: "random" as FlashOrderMode, label: t("review.flash.orderRandom") }
    ],
    [t]
  );

  const resetFlashSessionState = useCallback(() => {
    setFlashSessionVersion(0);
    flash.resetProgress?.();
  }, [flash.resetProgress]);

  const startFlashSession = useCallback(() => {
    if (!hasCards) return;
    setFlashSessionVersion((prev) => prev + 1);
  }, [hasCards]);

  const handleFlashOrderChange = useCallback(
    (value: FlashOrderMode) => {
      if (value === flashOrder) return;
      setFlashOrder(value);
      resetFlashSessionState();
    },
    [flashOrder, resetFlashSessionState]
  );

  const handleOrientationChange = useCallback(
    (value: ReviewOrientation) => {
      if (value === orientation) return;
      setOrientation(value);
      resetFlashSessionState();
    },
    [orientation, resetFlashSessionState]
  );
  const reverseOrientation = useCallback(() => {
    handleOrientationChange(orientation === "front-first" ? "back-first" : "front-first");
  }, [orientation, handleOrientationChange]);

  useEffect(() => {
    if (!isOpen) {
      resetFlashSessionState();
    }
  }, [isOpen, resetFlashSessionState]);

  useEffect(() => {
    if (!isOpen || !hasCards) return;
    resetFlashSessionState();
  }, [deckId, isOpen, hasCards, resetFlashSessionState]);

  useEffect(() => {
    if (!isOpen || !hasCards) return;
    resetFlashSessionState();
  }, [flashOrder, orientation, isOpen, hasCards, resetFlashSessionState]);

  useEffect(() => {
    if (!isOpen || !hasCards) return;
    if (flashSessionVersion === 0) return;
    flash.resetProgress?.();
    flash.startNewSession?.();
  }, [isOpen, hasCards, flashSessionVersion, flash.resetProgress, flash.startNewSession]);

  return (
    <GlassModal open={isOpen} onClose={onClose} panelClassName="max-w-4xl" contentClassName="text-slate-900 dark:text-slate-50">
      <header className="flex flex-wrap items-start justify-between gap-3 md:gap-4">
        <div className="space-y-2">
          <p className="flex items-center gap-2 text-xs uppercase tracking-wide text-brand-400">
            <span className="text-brand-500">
              <FlashcardsIcon className="h-4 w-4" />
            </span>
            {t("review.mode.flashcardsLabel")}
          </p>
          <h2 className="text-xl md:text-2xl font-semibold text-slate-900 dark:text-slate-50">
            {deck ? deck.title : t("review.selectDeck")}
          </h2>
          {deck?.description && (
            <p className="hidden md:block text-sm text-slate-700 dark:text-slate-400">{deck.description}</p>
          )}
          <p className="hidden md:block text-sm text-slate-700 dark:text-slate-500">{t("review.startDescription")}</p>
        </div>
      </header>

      {hasCards && (
        <div className="ui-card-panel text-sm ui-vstack-3">
          <div className="ui-flash-settings-grid">
            <div className="ui-flash-settings-section">
              <span className="ui-kicker">
                {t("review.flash.orderLabel")}
              </span>
              <div className="ui-flash-toggle-row">
                {flashOrderOptions.map((option) => {
                  const active = flashOrder === option.value;
                  return (
                    <Button
                      key={option.value}
                      size="sm"
                      variant={active ? "secondary" : "outline"}
                      className={clsx(active && "ui-btn-emerald-soft")}
                      onClick={() => handleFlashOrderChange(option.value)}
                    >
                      {option.label}
                    </Button>
                  );
                })}
              </div>
            </div>
            <div className="ui-flash-settings-section">
              <span className="ui-kicker">
                {t("review.flash.orientationLabel")}
              </span>
              <div className="ui-flash-toggle-row">
                <Button
                  size="sm"
                  variant={orientation === "front-first" ? "secondary" : "outline"}
                  className={clsx("ui-nowrap", orientation === "front-first" && "ui-btn-emerald-soft")}
                  onClick={() => handleOrientationChange("front-first")}
                >
                  {t("review.cardFront")} ↦ {t("review.cardBack")}
                </Button>
                <Button
                  size="sm"
                  variant={orientation === "back-first" ? "secondary" : "outline"}
                  className={clsx("ui-nowrap", orientation === "back-first" && "ui-btn-emerald-soft")}
                  onClick={() => handleOrientationChange("back-first")}
                >
                  {t("review.cardBack")} ↦ {t("review.cardFront")}
                </Button>
              </div>
            </div>
          </div>
          <div className="ui-flash-action-row">
            <Button
              size="sm"
              variant="secondary"
              className="ui-btn-emerald-soft"
              onClick={startFlashSession}
              disabled={!hasCards}
            >
              {flashSessionVersion > 0 ? t("review.flash.restartButton") : t("review.flash.startButton")}
            </Button>
          </div>
        </div>
      )}

      {reviewState && (
        <div className="ui-review-summary-row">
          <div className="ui-review-summary-card is-unknown">
            <span className="ui-review-summary-count">{totalUnknown}</span>
            <span className="ui-review-summary-label">
              {t("review.statsUnknownLabel")}
            </span>
          </div>
          <div className="ui-review-summary-card is-known">
            <span className="ui-review-summary-count">{totalKnown}</span>
            <span className="ui-review-summary-label">
              {t("review.statsKnownLabel")}
            </span>
          </div>
        </div>
      )}

      {!hasCards && (
        <div className="ui-empty-panel">
          {t("review.emptyDeck")}
        </div>
      )}

      {hasCards && inProgress && currentCard && (
        <ReviewCard
          front={currentCard.front}
          back={currentCard.back}
          onKnow={flash.markCardAsKnown}
          onDontKnow={flash.markCardAsUnknown}
          onReverseOrientation={reverseOrientation}
        />
      )}

      {hasCards && inProgress && progressLabel && (
        <div className="mt-3 text-xs font-semibold uppercase tracking-wide text-brand-500">
          {progressLabel}
        </div>
      )}

      {hasCards && inProgress && (
        <div className="mt-2 grid gap-2 sm:grid-cols-2">
          <Button size="sm" variant="warning" onClick={flash.markCardAsUnknown}>
            {t("review.markUnknown")}
          </Button>
          <Button size="sm" variant="primary" onClick={flash.markCardAsKnown}>
            {t("review.markKnown")}
          </Button>
        </div>
      )}

      {hasCards && isSummary && reviewState && (
        <ReviewStats
          totalCards={totalKnown + totalUnknown}
          knownCards={totalKnown}
          unknownCards={totalUnknown}
          round={reviewState.round}
          nextRoundUnknown={nextRoundUnknownCount}
          onRestartUnknown={() => {
            if (canReviewUnknown) {
              startUnknownRound?.();
            }
          }}
        />
      )}

      {hasCards && inProgress && (
        <footer className="hidden md:flex md:flex-wrap md:items-center md:justify-between md:gap-3">
          <div className="ui-text-xs-muted">
            {t("review.swipeInstruction")}
          </div>
        </footer>
      )}
    </GlassModal>
  );
};
